import { z } from "zod";

export const runStatusSchema = z.enum([
  "QUEUED",
  "CONNECTING",
  "RUNNING",
  "WAITING_PERMISSION",
  "VERIFYING",
  "SUCCEEDED",
  "FAILED",
  "CANCELLED",
  "UNKNOWN",
]);

export type RunStatus = z.infer<typeof runStatusSchema>;

export const terminalRunStatuses = ["SUCCEEDED", "FAILED", "CANCELLED"] as const satisfies readonly RunStatus[];
export const settledRunStatuses = [...terminalRunStatuses, "UNKNOWN"] as const satisfies readonly RunStatus[];

export function isTerminalRunStatus(status: RunStatus): boolean {
  return (terminalRunStatuses as readonly RunStatus[]).includes(status);
}

export function isSettledRunStatus(status: RunStatus): boolean {
  return (settledRunStatuses as readonly RunStatus[]).includes(status);
}

const transitions: Record<RunStatus, readonly RunStatus[]> = {
  QUEUED: ["CONNECTING", "FAILED", "CANCELLED", "UNKNOWN"],
  CONNECTING: ["RUNNING", "WAITING_PERMISSION", "FAILED", "CANCELLED", "UNKNOWN"],
  RUNNING: ["WAITING_PERMISSION", "VERIFYING", "SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"],
  WAITING_PERMISSION: ["RUNNING", "VERIFYING", "FAILED", "CANCELLED", "UNKNOWN"],
  VERIFYING: ["SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"],
  SUCCEEDED: [],
  FAILED: [],
  CANCELLED: [],
  // UNKNOWN is reconcilable, but it never returns to QUEUED. Reconciliation must
  // never enqueue a second native attempt.
  UNKNOWN: ["RUNNING", "RUNNING", "VERIFYING", "SUCCEEDED", "FAILED", "CANCELLED"],
};

export function canTransitionRun(from: RunStatus, to: RunStatus): boolean {
  if (from === to) return true;
  return transitions[from].includes(to);
}

export const runEventCategorySchema = z.enum([
  "run",
  "connection",
  "session",
  "model",
  "tool",
  "permission",
  "file",
  "verification",
  "evidence",
  "error",
  "heartbeat",
]);

export type RunEventCategory = z.infer<typeof runEventCategorySchema>;

export const runEventSchema = z.object({
  version: z.literal(1),
  seq: z.number().int().positive(),
  runId: z.string(),
  at: z.string(),
  category: runEventCategorySchema,
  type: z.string().max(120),
  summary: z.string().max(1_000),
  metadata: z.record(z.string(), z.unknown()),
  evidence: z.array(z.object({
    kind: z.string().max(80),
    reference: z.string().max(500),
  })).max(20),
});

export type RunEvent = z.infer<typeof runEventSchema>;

export const runDiffFileSchema = z.object({
  file: z.string().max(1_000),
  status: z.enum(["added", "deleted", "modified"]),
  additions: z.number().int().nonnegative(),
  deletions: z.number().int().nonnegative(),
});

export type RunDiffFile = z.infer<typeof runDiffFileSchema>;

export const runVerificationSchema = z.object({
  checkId: z.literal("CK-06"),
  result: z.enum(["PASS", "FAIL", "NOT_RUN", "INCONCLUSIVE"]),
  fingerprint: z.string(),
  observedAt: z.string(),
  summary: z.string().max(4_000),
  limitation: z.string().nullable(),
});

export type RunVerification = z.infer<typeof runVerificationSchema>;

export const runUsageSchema = z.object({
  cost: z.number().nonnegative().nullable(),
  input: z.number().int().nonnegative().nullable(),
  output: z.number().int().nonnegative().nullable(),
  reasoning: z.number().int().nonnegative().nullable(),
  cacheRead: z.number().int().nonnegative().nullable(),
  cacheWrite: z.number().int().nonnegative().nullable(),
});

export type RunUsage = z.infer<typeof runUsageSchema>;

export const runErrorSchema = z.object({
  code: z.string().max(120),
  message: z.string().max(2_000),
  retryable: z.boolean(),
});

export type RunError = z.infer<typeof runErrorSchema>;

export const runPermissionSchema = z.object({
  requestId: z.string().max(300).nullable(),
  action: z.string().max(120).nullable(),
  resources: z.array(z.string().max(300)).max(20),
  status: z.enum(["requested", "replied"]),
});

export type RunPermission = z.infer<typeof runPermissionSchema>;

export const runRecordSchema = z.object({
  schemaVersion: z.literal(1),
  id: z.string(),
  projectId: z.string(),
  actionId: z.string(),
  payloadHash: z.string(),
  status: runStatusSchema,
  createdAt: z.string(),
  updatedAt: z.string(),
  startedAt: z.string().nullable(),
  completedAt: z.string().nullable(),
  durationMs: z.number().int().nonnegative().nullable(),
  sessionId: z.string().nullable(),
  messageId: z.string().nullable(),
  model: z.string().nullable(),
  lastEventSeq: z.number().int().nonnegative(),
  lastSummary: z.string().max(1_000),
  cancelRequestedAt: z.string().nullable(),
  cancelActionId: z.string().nullable(),
  interruptAccepted: z.boolean().nullable(),
  reconciledAt: z.string().nullable(),
  terminalReason: z.string().max(120).nullable(),
  error: runErrorSchema.nullable(),
  permission: runPermissionSchema.nullable(),
  diff: z.array(runDiffFileSchema).max(200),
  verification: runVerificationSchema.nullable(),
  usage: runUsageSchema.nullable(),
  limitation: z.string().max(2_000).nullable(),
  evidence: z.array(z.object({
    kind: z.string().max(80),
    reference: z.string().max(500),
  })).max(40),
  events: z.array(runEventSchema),
});

export type RunRecord = z.infer<typeof runRecordSchema>;

export interface RunSummary {
  id: string;
  projectId: string;
  status: RunStatus;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  durationMs: number | null;
  sessionId: string | null;
  messageId: string | null;
  model: string | null;
  lastEventSeq: number;
  lastSummary: string;
  terminalReason: string | null;
  error: RunError | null;
  diff: RunDiffFile[];
  verification: RunVerification | null;
  usage: RunUsage | null;
  limitation: string | null;
}

const SECRET_KEY = REDACTED;
const SECRET_VALUE_PATTERNS: Array<[RegExp, string]> = [
  [/\bBearer\s+[A-Za-z0-9._~+/=-]{8,}\b/gi, "Bearer [REDACTED]"],
  [/\bBasic\s+[A-Za-z0-9+/=]{8,}\b/gi, "Basic [REDACTED]"],
  [/\bsk-[A-Za-z0-9_-]{8,}\b/g, "[REDACTED_API_KEY]"],
  [/\bgh[pousr]_[A-Za-z0-9]{8,}\b/g, "[REDACTED_TOKEN]"],
  [/\bxox[baprs]-[A-Za-z0-9-]{8,}\b/g, "[REDACTED_TOKEN]"],
  [/((?:api[-_]?key|token|secret|password|passwd|authorization|cookie)\s*[:=]\s*)("?)([^\s"',;]{3,})\2/gi, "$1$2[REDACTED]$2"],
  [/([?&](?:token|key|secret|password|code)=)[^&\s]+/gi, "$1[REDACTED]"],
];

export function redactString(value: string, maximum = 1_000): string {
  let output = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "");
  for (const [pattern, replacement] of SECRET_VALUE_PATTERNS) {
    output = output.replace(pattern, replacement);
  }
  if (output.length > maximum) output = `${output.slice(0, maximum - 1)}…`;
  return output;
}

export function redactMetadata(value: unknown, depth = 0): unknown {
  if (value === null || value === undefined) return null;
  if (depth > 4) return "[TRUNCATED]";
  if (typeof value === "string") return redactString(value, 500);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.slice(0, 20).map((item) => redactMetadata(item, depth + 1));
  if (typeof value === "object") {
    const output: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value as Record<string, unknown>).slice(0, 30)) {
      output[key] = SECRET_KEY.test(key) ? "[REDACTED]" : redactMetadata(item, depth + 1);
    }
    return output;
  }
  return "[UNSUPPORTED]";
}

export function redactMetadataObject(value: Record<string, unknown>): Record<string, unknown> {
  return redactMetadata(value) as Record<string, unknown>;
}

export function classifyNativeError(error: unknown): { code: string; message: string; retryable: boolean } {
  const raw = error instanceof Error ? error.message : String(error ?? "");
  const message = redactString(raw || "The native operation failed.", 2_000);
  const lower = message.toLowerCase();
  if (/401|unauthor|authentication|invalid.*(?:password|credential|token)/i.test(lower)) {
    return { code: "AUTHENTICATION_FAILED", message, retryable: false };
  }
  if (/403|permission denied|forbidden|not allowed|denied/i.test(lower)) {
    return { code: "PERMISSION_DENIED", message, retryable: false };
  }
  if (/429|rate limit|quota|usage limit|provider limit|overloaded|too many requests/i.test(lower)) {
    return { code: "PROVIDER_LIMIT", message, retryable: true };
  }
  if (/model.*(?:not found|missing|unavailable)|unknown model|no such model/i.test(lower)) {
    return { code: "MODEL_UNAVAILABLE", message, retryable: false };
  }
  if (/timed out|timeout|deadline|abort/i.test(lower)) {
    return { code: "NATIVE_TIMEOUT", message, retryable: true };
  }
  if (/econn|fetch failed|network|socket|unavailable|connection refused/i.test(lower)) {
    return { code: "OPENCODE_UNAVAILABLE", message, retryable: true };
  }
  return { code: "NATIVE_FAILED", message, retryable: false };
}

import type { RunEventCategory, RunPermission } from "../../shared/runs.ts";
import { redactMetadataObject, redactString } from "./redaction.ts";

export interface NativeRunEvent {
  type: string;
  at?: string;
  data?: Record<string, unknown>;
  malformed?: boolean;
}

export interface NormalizedNativeEvent {
  category: RunEventCategory;
  type: string;
  summary: string;
  metadata: Record<string, unknown>;
  status?: "RUNNING" | "WAITING_PERMISSION";
  permission?: RunPermission;
  terminal?: boolean;
}

function text(value: unknown, maximum = 300): string | null {
  return typeof value === "string" && value.trim().length > 0 ? redactString(value.trim(), maximum) : null;
}

function resources(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.slice(0, 10).map((item) => text(item, 300) ?? "[unnamed]");
}

export function normalizeNativeEvent(input: NativeRunEvent): NormalizedNativeEvent {
  const type = typeof input.type === "string" ? input.type.slice(0, 120) : "unknown";
  const at = typeof input.at === "string" ? input.at : new Date().toISOString();
  const data = input.data ?? {};

  if (input.malformed) {
    return {
      category: "error",
      type: "native.malformed",
      summary: "A malformed native event was ignored. The run continues with the last confirmed state.",
      metadata: redactMetadataObject({ nativeType: type, at }),
    };
  }

  switch (type) {
    case "session.execution.started":
      return {
        category: "session",
        type,
        summary: "OpenCode started the native run.",
        metadata: redactMetadataObject({ at }),
        status: "RUNNING",
      };
    case "session.step.started":
      return {
        category: "model",
        type,
        summary: "The model started a step.",
        metadata: redactMetadataObject({ at, model: data.model }),
        status: "RUNNING",
      };
    case "session.text.ended": {
      const response = text(data.text, 400);
      return {
        category: "model",
        type,
        summary: response ? `Model response: ${response}` : "The model returned an empty response.",
        metadata: redactMetadataObject({ at, messageID: data.assistantMessageID }),
      };
    }
    case "session.tool.called":
      return {
        category: "tool",
        type,
        summary: `Using tool ${text(data.name, 80) ?? "unknown"}.`,
        metadata: redactMetadataObject({ at, tool: data.name }),
        status: "RUNNING",
      };
    case "session.tool.success":
    case "session.tool.failed": {
      const tool = text(data.name, 80);
      return {
        category: "tool",
        type,
        summary: type.endsWith("failed")
          ? `Tool ${tool ?? "operation"} failed. Its arguments and output were not stored.`
          : `Tool ${tool ?? "operation"} finished. Its arguments and output were not stored.`,
        metadata: redactMetadataObject({ at, tool }),
        status: "RUNNING",
      };
    }
    case "permission.asked": {
      const action = text(data.action, 120);
      const resourceList = resources(data.resources);
      return {
        category: "permission",
        type,
        summary: `Waiting for permission: ${action ?? "a native action"}${resourceList.length ? ` on ${resourceList.join(", ")}` : ""}.`,
        metadata: redactMetadataObject({ at, requestId: data.id, action, resources: resourceList }),
        status: "WAITING_PERMISSION",
        permission: {
          requestId: text(data.id, 300),
          action,
          resources: resourceList,
          status: "requested",
        },
      };
    }
    case "permission.replied": {
      const reply = text(data.reply, 40);
      return {
        category: "permission",
        type,
        summary: `Native permission ${reply === "reject" ? "denied" : "answered"}.`,
        metadata: redactMetadataObject({ at, requestID: data.requestID, reply }),
        status: "RUNNING",
        permission: {
          requestId: text(data.requestID, 300),
          action: null,
          resources: [],
          status: "replied",
        },
      };
    }
    case "session.retry.scheduled":
      return {
        category: "model",
        type,
        summary: "The provider asked OpenCode to retry. The native session remains active.",
        metadata: redactMetadataObject({ at, attempt: data.attempt }),
      };
    case "session.step.ended":
      return {
        category: "model",
        type,
        summary: "The model finished a step.",
        metadata: redactMetadataObject({
          at,
          finish: data.finish,
          cost: data.cost,
          input: (data.tokens as Record<string, unknown> | undefined)?.input,
          output: (data.tokens as Record<string, unknown> | undefined)?.output,
        }),
      };
    case "session.step.failed":
      return {
        category: "error",
        type,
        summary: "A native model step failed. OpenCode will report the session outcome.",
        metadata: redactMetadataObject({ at, finish: data.finish }),
      };
    case "session.execution.succeeded":
      return {
        category: "session",
        type,
        summary: "OpenCode reported that the native execution succeeded.",
        metadata: redactMetadataObject({ at }),
        terminal: true,
      };
    case "session.execution.failed":
      return {
        category: "error",
        type,
        summary: "OpenCode reported that the native execution failed.",
        metadata: redactMetadataObject({ at }),
        terminal: true,
      };
    case "session.execution.interrupted":
      return {
        category: "session",
        type,
        summary: "OpenCode reported that the native execution was interrupted.",
        metadata: redactMetadataObject({ at, reason: data.reason }),
        terminal: true,
      };
    case "session.idle":
      return {
        category: "session",
        type,
        summary: "OpenCode session became idle. Confirming the outcome.",
        metadata: redactMetadataObject({ at }),
        terminal: true,
      };
    case "session.status": {
      const status = data.status as { type?: unknown } | undefined;
      const statusType = typeof status?.type === "string" ? status.type : "unknown";
      return {
        category: "session",
        type,
        summary: statusType === "retry"
          ? "OpenCode is retrying the provider request."
          : statusType === "busy"
            ? "OpenCode is still working."
            : "OpenCode is idle.",
        metadata: redactMetadataObject({ at, status: statusType }),
        status: statusType === "idle" ? undefined : "RUNNING",
      };
    }
    case "session.usage.recorded":
    case "session.usage.updated":
      return {
        category: "evidence",
        type,
        summary: "OpenCode recorded session usage.",
        metadata: redactMetadataObject({ at, cost: data.cost }),
      };
    case "filesystem.changed":
      return {
        category: "file",
        type,
        summary: "OpenCode reported a workspace file change.",
        metadata: redactMetadataObject({ at }),
      };
    default:
      // Reasoning events and unknown event types are intentionally not exposed.
      return {
        category: "session",
        type: "native.other",
        summary: "OpenCode reported native activity.",
        metadata: redactMetadataObject({ at, nativeType: type }),
      };
  }
}

import { EventEmitter } from "node:events";
import { copyFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { createHash, randomUUID } from "node:crypto";
import { z } from "zod";
import {
  canTransitionRun,
  runEventSchema,
  runRecordSchema,
  type RunEvent,
  type RunRecord,
  type RunStatus,
} from "../../shared/runs.ts";
import { redactMetadataObject, redactString } from "./redaction.ts";

const runDocumentSchema = z.object({
  schemaVersion: z.literal(1),
  lastSequence: z.number().int().nonnegative(),
  runs: z.array(runRecordSchema),
});

type RunDocument = z.infer<typeof runDocumentSchema>;

export interface RunEventInput {
  category: RunEvent["category"];
  type: string;
  summary: string;
  metadata?: Record<string, unknown>;
  evidence?: RunEvent["evidence"];
  at?: string;
}

export interface CreateRunInput {
  projectId: string;
  actionId: string;
  payloadHash: string;
  model?: string | null;
}

export class RunTransitionError extends Error {}

export class RunStore {
  readonly previousPath: string;
  private readonly events = new EventEmitter();
  private writeQueue: Promise<unknown> = Promise.resolve();

  constructor(
    readonly path: string,
    private readonly options: { now?: () => Date } = {},
  ) {
    this.previousPath = `${path}.previous`;
    this.events.setMaxListeners(100);
  }

  private now(): Date {
    return this.options.now?.() ?? new Date();
  }

  private async read(): Promise<RunDocument> {
    try {
      const parsed = JSON.parse(await readFile(this.path, "utf8"));
      if (!parsed.schemaVersion) parsed.schemaVersion = 1;
      if (!Array.isArray(parsed.runs)) parsed.runs = [];
      if (typeof parsed.lastSequence !== "number") {
        parsed.lastSequence = parsed.runs
          .flatMap((run: RunRecord) => run.events.map((event) => event.seq))
          .reduce((maximum: number, seq: number) => Math.max(maximum, seq), 0);
      }
      return runDocumentSchema.parse(parsed);
    } catch (error) {
      try {
        return runDocumentSchema.parse(JSON.parse(await readFile(this.previousPath, "utf8")));
      } catch {
        throw error;
      }
    }
  }

  private async write(document: RunDocument): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    const validated = runDocumentSchema.parse(document);
    const temporaryPath = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    try {
      await copyFile(this.path, this.previousPath);
    } catch {
      // The first write has no previous snapshot.
    }
    await writeFile(temporaryPath, `${JSON.stringify(validated, null, 2)}\n`, { flag: "wx" });
    await rename(temporaryPath, this.path);
  }

  private serial<T>(work: () => Promise<T>): Promise<T> {
    const next = this.writeQueue.then(work, work);
    this.writeQueue = next.catch(() => undefined);
    return next;
  }

  async initialize(): Promise<void> {
    try {
      await readFile(this.path);
    } catch {
      await this.write({ schemaVersion: 1, lastSequence: 0, runs: [] });
    }
  }

  async get(runId: string): Promise<RunRecord | null> {
    const document = await this.read();
    return document.runs.find((run) => run.id === runId) ?? null;
  }

  async list(): Promise<RunRecord[]> {
    return (await this.read()).runs.toSorted((left, right) => right.createdAt.localeCompare(left.createdAt));
  }

  async latest(projectId?: string): Promise<RunRecord | null> {
    return (await this.list()).find((run) => !projectId || run.projectId === projectId) ?? null;
  }

  async findByActionId(actionId: string): Promise<RunRecord | null> {
    return (await this.list()).find((run) => run.actionId === actionId) ?? null;
  }

  async listNonTerminal(): Promise<RunRecord[]> {
    return (await this.list()).filter((run) =>
      ["QUEUED", "CONNECTING", "RUNNING", "WAITING_PERMISSION", "VERIFYING"].includes(run.status));
  }

  async activeForProject(projectId: string): Promise<RunRecord | null> {
    return (await this.list()).find((run) =>
      run.projectId === projectId
      && ["QUEUED", "CONNECTING", "RUNNING", "WAITING_PERMISSION", "VERIFYING"].includes(run.status)) ?? null;
  }

  create(input: CreateRunInput): Promise<RunRecord> {
    return this.serial(async () => {
      const document = await this.read();
      const now = this.now().toISOString();
      const runId = randomUUID();
      const sequence = document.lastSequence + 1;
      const event = runEventSchema.parse({
        version: 1,
        seq: sequence,
        runId,
        at: now,
        category: "run",
        type: "run.queued",
        summary: "Run saved and queued. No model work has started yet.",
        metadata: { status: "QUEUED" },
        evidence: [],
      });
      const run = runRecordSchema.parse({
        schemaVersion: 1,
        id: runId,
        projectId: input.projectId,
        actionId: input.actionId,
        payloadHash: input.payloadHash,
        status: "QUEUED",
        createdAt: now,
        updatedAt: now,
        startedAt: null,
        completedAt: null,
        durationMs: null,
        sessionId: null,
        messageId: null,
        model: input.model ?? null,
        lastEventSeq: sequence,
        lastSummary: event.summary,
        cancelRequestedAt: null,
        cancelActionId: null,
        interruptAccepted: null,
        reconciledAt: null,
        terminalReason: null,
        error: null,
        permission: null,
        diff: [],
        verification: null,
        usage: null,
        limitation: null,
        evidence: [],
        events: [event],
      });
      document.runs.push(run);
      document.lastSequence = sequence;
      await this.write(document);
      this.events.emit(runId, event);
      return run;
    });
  }

  async update(runId: string, mutator: (run: RunRecord) => RunRecord): Promise<RunRecord> {
    return this.mutate(runId, mutator, null);
  }

  async appendEvent(runId: string, input: RunEventInput): Promise<RunRecord> {
    return this.mutate(runId, (run) => run, input);
  }

  async transition(
    runId: string,
    status: RunStatus,
    patch: Partial<RunRecord> = {},
    event?: RunEventInput,
  ): Promise<RunRecord> {
    return this.serial(async () => {
      const document = await this.read();
      const index = document.runs.findIndex((run) => run.id === runId);
      if (index < 0) throw new RunTransitionError(`Run ${runId} was not found.`);
      const current = document.runs[index];
      if (!canTransitionRun(current.status, status)) {
        throw new RunTransitionError(`Run cannot move from ${current.status} to ${status}.`);
      }
      const now = this.now().toISOString();
      const next = runRecordSchema.parse({
        ...structuredClone(current),
        ...patch,
        status,
        updatedAt: now,
        startedAt: patch.startedAt ?? current.startedAt ?? (status === "CONNECTING" ? now : current.startedAt),
        completedAt: patch.completedAt ?? current.completedAt,
      });
      if (event) {
        const appended = this.appendToRun(next, document, event);
        document.runs[index] = appended.run;
        document.lastSequence = appended.sequence;
        await this.write(document);
        this.events.emit(runId, appended.event);
        return appended.run;
      }
      document.runs[index] = next;
      await this.write(document);
      return next;
    });
  }

  async waitForSettled(runId: string, timeoutMs = 5_000): Promise<RunRecord | null> {
    const current = await this.get(runId);
    if (!current) return null;
    if (["SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"].includes(current.status)) return current;
    return new Promise((resolve) => {
      const timer = setTimeout(() => {
        cleanup();
        void this.get(runId).then(resolve);
      }, timeoutMs);
      const listener = (event: RunEvent) => {
        const status = event.metadata.status;
        if (typeof status === "string" && ["SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"].includes(status)) {
          cleanup();
          void this.get(runId).then(resolve);
        }
      };
      const cleanup = () => {
        clearTimeout(timer);
        this.events.off(runId, listener);
      };
      this.events.on(runId, listener);
    });
  }

  subscribe(runId: string, listener: (event: RunEvent) => void): () => void {
    this.events.on(runId, listener);
    return () => this.events.off(runId, listener);
  }

  private async mutate(
    runId: string,
    mutator: (run: RunRecord) => RunRecord,
    event: RunEventInput | null,
  ): Promise<RunRecord> {
    return this.serial(async () => {
      const document = await this.read();
      const index = document.runs.findIndex((run) => run.id === runId);
      if (index < 0) throw new RunTransitionError(`Run ${runId} was not found.`);
      const current = document.runs[index];
      const now = this.now().toISOString();
      let next = runRecordSchema.parse({
        ...structuredClone(mutator(structuredClone(current))),
        updatedAt: now,
      });
      if (event) {
        const appended = this.appendToRun(next, document, event);
        next = appended.run;
        document.lastSequence = appended.sequence;
        document.runs[index] = next;
        await this.write(document);
        this.events.emit(runId, appended.event);
        return next;
      }
      document.runs[index] = next;
      await this.write(document);
      return next;
    });
  }

  private appendToRun(run: RunRecord, document: RunDocument, input: RunEventInput) {
    const sequence = document.lastSequence + 1;
    const event = runEventSchema.parse({
      version: 1,
      seq: sequence,
      runId: run.id,
      at: input.at ?? this.now().toISOString(),
      category: input.category,
      type: input.type,
      summary: redactString(input.summary, 1_000),
      metadata: redactMetadataObject({ ...input.metadata, status: input.metadata?.status ?? run.status }),
      evidence: input.evidence ?? [],
    });
    return {
      sequence,
      event,
      run: runRecordSchema.parse({
        ...run,
        lastEventSeq: sequence,
        lastSummary: event.summary,
        events: [...run.events, event],
      }),
    };
  }
}

export function hashPayload(payload: unknown): string {
  return createHash("sha256").update(JSON.stringify(payload, Object.keys(payload as object).sort())).digest("hex");
}

import {
  createNativeClient,
  FREE_DEEPSEEK_MODEL,
  type NativeClientOptions,
} from "./client.ts";
import type { RunDiffFile, RunUsage } from "../../shared/runs.ts";
import type { NativeRunEvent } from "../runs/events.ts";

export type NativeOutcome = "succeeded" | "failed" | "interrupted" | null;

export interface NativeSessionIdentity {
  sessionId: string;
  model: string | null;
}

export interface NativeInspection {
  sessionId: string;
  outcome: NativeOutcome;
  idle: boolean;
  model: string | null;
  usage: RunUsage;
}

export interface NativeRunDriver {
  createSession(input: {
    projectId: string;
    workspace: string;
    title: string;
  }): Promise<NativeSessionIdentity>;
  prompt(input: { sessionId: string; text: string }): Promise<{ messageId: string | null }>;
  interrupt(sessionId: string): Promise<{ interrupted: boolean }>;
  inspect(sessionId: string): Promise<NativeInspection>;
  diff(sessionId: string): Promise<RunDiffFile[]>;
  follow(
    sessionId: string,
    onEvent: (event: NativeRunEvent) => void,
    signal: AbortSignal,
  ): Promise<void>;
}

const makerPermissions = [
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
  { action: "edit", resource: "*", effect: "allow" as const },
];

function toUsage(info: { cost: number; tokens?: { input: number; output: number; reasoning: number; cache: { read: number; write: number } } }): RunUsage {
  return {
    cost: Number.isFinite(info.cost) ? info.cost : null,
    input: info.tokens?.input ?? null,
    output: info.tokens?.output ?? null,
    reasoning: info.tokens?.reasoning ?? null,
    cacheRead: info.tokens?.cache?.read ?? null,
    cacheWrite: info.tokens?.cache?.write ?? null,
  };
}

function assertFreeModel(model: { providerID: string; id: string } | undefined, cost: number): void {
  const selected = model ? `${model.providerID}/${model.id}` : "";
  if (selected !== FREE_DEEPSEEK_MODEL) {
    throw new Error(`Native session left the required free DeepSeek model (${selected || "unreported"}).`);
  }
  if (cost > 0) throw new Error("Native session reported a non-zero cost.");
}

export class OpenCodeRunDriver implements NativeRunDriver {
  constructor(private readonly options: NativeClientOptions) {}

  private client() {
    return createNativeClient(this.options);
  }

  async createSession(input: { projectId: string; workspace: string; title: string }): Promise<NativeSessionIdentity> {
    const created = await this.client().session.create({
      title: input.title,
      model: { providerID: "opencode", id: "deepseek-v4.1-flash-free" },
      location: { directory: input.workspace },
      permissions: makerPermissions,
    });
    return {
      sessionId: created.id,
      model: created.model ? `${created.model.providerID}/${created.model.id}` : FREE_DEEPSEEK_MODEL,
    };
  }

  async prompt(input: { sessionId: string; text: string }): Promise<{ messageId: string | null }> {
    const prompted = await this.client().session.prompt({
      sessionID: input.sessionId,
      text: input.text,
    });
    return { messageId: typeof prompted.id === "string" ? prompted.id : null };
  }

  async interrupt(sessionId: string): Promise<{ interrupted: boolean }> {
    const result = await this.client().session.interrupt({ sessionID: sessionId });
    return { interrupted: Boolean(result.interrupted) };
  }

  async inspect(sessionId: string): Promise<NativeInspection> {
    const info = await this.client().session.get({ sessionID: sessionId });
    assertFreeModel(info.model, info.cost);
    return {
      sessionId,
      outcome: info.outcome ?? null,
      idle: Boolean(info.time.idle),
      model: info.model ? `${info.model.providerID}/${info.model.id}` : null,
      usage: toUsage(info),
    };
  }

  async diff(sessionId: string): Promise<RunDiffFile[]> {
    const result = await this.client().session.diff({ sessionID: sessionId });
    return result.slice(0, 200).map((file) => ({
      file: file.file,
      status: file.status,
      additions: file.additions,
      deletions: file.deletions,
    }));
  }

  async follow(
    sessionId: string,
    onEvent: (event: NativeRunEvent) => void,
    signal: AbortSignal,
  ): Promise<void> {
    for await (const event of this.client().event.subscribe({ signal })) {
      const data = (event as { data?: Record<string, unknown> }).data;
      if (data?.sessionID !== sessionId) continue;
      const normalized: NativeRunEvent = {
        type: String((event as { type?: unknown }).type ?? "unknown"),
        at: new Date(Number((event as { created?: unknown }).created ?? Date.now())).toISOString(),
        data,
      };
      onEvent(normalized);
      if (["session.idle", "session.execution.succeeded", "session.execution.failed", "session.execution.interrupted"].includes(normalized.type)) {
        return;
      }
    }
  }
}

import type {
  RunDiffFile,
  RunRecord,
  RunStatus,
  RunUsage,
  RunVerification,
} from "../../shared/runs.ts";
import { isSettledRunStatus, isTerminalRunStatus } from "../../shared/runs.ts";
import type { NativeRunDriver, NativeInspection } from "../opencode/run-driver.ts";
import { classifyNativeError, redactString } from "./redaction.ts";
import { normalizeNativeEvent, type NativeRunEvent } from "./events.ts";
import { RunStore, RunTransitionError, type RunEventInput } from "./store.ts";

export interface RunPlan {
  prompt: string;
  workspace: string;
}

export interface RunCoordinatorOptions {
  driver: NativeRunDriver;
  store: RunStore;
  verify: (input: { workspace: string; diff: RunDiffFile[] }) => Promise<RunVerification>;
  onSettled: (run: RunRecord) => Promise<void>;
  timeoutMs?: number;
  cancelObserveMs?: number;
  pollIntervalMs?: number;
  heartbeatIntervalMs?: number;
  maxConcurrent?: number;
  maxQueue?: number;
  now?: () => Date;
}

export class RunQueueFullError extends Error {}
export class RunConflictError extends Error {}

const ACTIVE = ["QUEUED", "CONNECTING", "RUNNING", "WAITING_PERMISSION", "VERIFYING"] as const;

function sleep(milliseconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

export class RunCoordinator {
  private readonly queue: Array<{ runId: string; plan: RunPlan }> = [];
  private readonly plans = new Map<string, RunPlan>();
  private readonly controllers = new Map<string, AbortController>();
  private readonly locks = new Map<string, Promise<unknown>>();
  private active = 0;
  private readonly timeoutMs: number;
  private readonly cancelObserveMs: number;
  private readonly pollIntervalMs: number;
  private readonly maxConcurrent: number;
  private readonly maxQueue: number;
  private readonly now: () => Date;

  constructor(private readonly options: RunCoordinatorOptions) {
    this.timeoutMs = options.timeoutMs ?? 180_000;
    this.cancelObserveMs = options.cancelObserveMs ?? 5_000;
    this.pollIntervalMs = options.pollIntervalMs ?? 250;
    this.maxConcurrent = options.maxConcurrent ?? 1;
    this.maxQueue = options.maxQueue ?? 8;
    this.now = options.now ?? (() => new Date());
    this.options.store.subscribe("*", () => undefined);
  }

  get activeCount(): number {
    return this.active;
  }

  get queuedCount(): number {
    return this.queue.length;
  }

  enqueue(runId: string, plan: RunPlan): void {
    if (this.queue.length >= this.maxQueue) {
      throw new RunQueueFullError("The run coordinator is full. Wait for the active run to finish.");
    }
    this.plans.set(runId, plan);
    this.queue.push({ runId, plan });
    void this.pump();
  }

  private async pump(): Promise<void> {
    while (this.active < this.maxConcurrent && this.queue.length > 0) {
      const item = this.queue.shift()!;
      this.active += 1;
      void this.process(item.runId, item.plan).finally(() => {
        this.active -= 1;
        if (isSettledRunStatusSafe(this.plans, item.runId)) this.plans.delete(item.runId);
        void this.pump();
      });
    }
  }

  private lock<T>(runId: string, work: () => Promise<T>): Promise<T> {
    const previous = this.locks.get(runId) ?? Promise.resolve();
    const next = previous.then(work, work);
    this.locks.set(runId, next.catch(() => undefined));
    return next;
  }

  private async process(runId: string, plan: RunPlan): Promise<void> {
    let workSent = false;
    let sessionId: string | null = null;
    try {
      await this.options.store.transition(runId, "CONNECTING", {}, {
        category: "connection",
        type: "run.connecting",
        summary: "Connecting to the local OpenCode server.",
        metadata: { status: "CONNECTING" },
      });
      const created = await this.options.driver.createSession({
        projectId: (await this.options.store.get(runId))?.projectId ?? "",
        workspace: plan.workspace,
        title: "Unfinished Business Maker",
      });
      sessionId = created.sessionId;
      // Persist the native identity before prompting. Work that can mutate files
      // must never start without a recoverable session reference.
      await this.options.store.update(runId, (run) => ({
        ...run,
        sessionId: created.sessionId,
        model: created.model,
      }));
      await this.options.store.appendEvent(runId, {
        category: "session",
        type: "session.persisted",
        summary: "Native session saved before any work was sent.",
        metadata: { sessionId: created.sessionId },
        evidence: [{ kind: "session", reference: created.sessionId }],
      });
      await this.options.store.transition(runId, "RUNNING", {}, {
        category: "run",
        type: "run.running",
        summary: "OpenCode session is ready. Sending the approved Maker scope.",
        metadata: { status: "RUNNING", sessionId: created.sessionId },
      });
      const prompted = await this.options.driver.prompt({ sessionId, text: plan.prompt });
      workSent = true;
      await this.options.store.update(runId, (run) => ({ ...run, messageId: prompted.messageId }));
      await this.options.store.appendEvent(runId, {
        category: "model",
        type: "run.prompt-sent",
        summary: "Work was sent to OpenCode. Waiting for the native session.",
        metadata: { status: "RUNNING", messageId: prompted.messageId },
      });
      const controller = new AbortController();
      this.controllers.set(runId, controller);
      const follow = this.options.driver.follow(
        sessionId,
        (event) => void this.onNativeEvent(runId, event),
        controller.signal,
      );
      await this.awaitNative(runId, sessionId, follow, plan);
    } catch (error) {
      await this.handleError(runId, error, { workSent, sessionId });
    } finally {
      this.controllers.delete(runId);
    }
  }

  private async awaitNative(
    runId: string,
    sessionId: string,
    follow: Promise<void>,
    plan: RunPlan,
  ): Promise<void> {
    let timedOut = false;
    let followError: unknown = null;
    const timer = sleep(this.timeoutMs).then(() => {
      timedOut = true;
    });
    try {
      await Promise.race([
        follow.catch((error: unknown) => {
          followError = error;
        }),
        timer,
      ]);
    } catch {
      // The race above already captures follow failures.
    }

    if (timedOut) {
      const inspection = await this.safeInspect(sessionId);
      if (inspection?.outcome) return this.finalizeInspection(runId, inspection, plan);
      return this.markUnknown(runId, {
        code: "NATIVE_TIMEOUT",
        message: "The run timed out. The native session reference was retained for reconciliation.",
        retryable: true,
      });
    }

    if (followError) {
      const inspection = await this.safeInspect(sessionId);
      if (inspection?.outcome) return this.finalizeInspection(runId, inspection, plan);
      if (inspection && !inspection.idle) {
        const polled = await this.pollUntilSettled(sessionId);
        if (polled?.outcome) return this.finalizeInspection(runId, polled, plan);
      }
      const classified = classifyNativeError(followError);
      return this.markUnknown(runId, {
        ...classified,
        message: "The event stream ended without a confirmed native outcome. The session was not repeated.",
      });
    }

    const inspection = await this.safeInspect(sessionId);
    if (!inspection) {
      return this.markUnknown(runId, {
        code: "NATIVE_STATUS_UNAVAILABLE",
        message: "OpenCode did not return a status for the saved session. No retry was attempted.",
        retryable: true,
      });
    }
    if (!inspection.outcome && !inspection.idle) {
      const polled = await this.pollUntilSettled(sessionId);
      if (polled) return this.finalizeInspection(runId, polled, plan);
    }
    return this.finalizeInspection(runId, inspection, plan);
  }

  private async pollUntilSettled(sessionId: string): Promise<NativeInspection | null> {
    const deadline = Date.now() + Math.min(this.timeoutMs, 30_000);
    while (Date.now() < deadline) {
      await sleep(this.pollIntervalMs);
      const inspection = await this.safeInspect(sessionId);
      if (inspection?.outcome) return inspection;
      if (inspection?.idle) return inspection;
    }
    return this.safeInspect(sessionId);
  }

  private async safeInspect(sessionId: string): Promise<NativeInspection | null> {
    try {
      return await this.options.driver.inspect(sessionId);
    } catch {
      return null;
    }
  }

  private async onNativeEvent(runId: string, event: NativeRunEvent): Promise<void> {
    const normalized = normalizeNativeEvent(event);
    try {
      const current = await this.options.store.get(runId);
      if (!current || isTerminalRunStatus(current.status)) return;
      if (normalized.status === "WAITING_PERMISSION" && current.status !== "WAITING_PERMISSION") {
        await this.options.store.transition(runId, "WAITING_PERMISSION", {
          permission: normalized.permission ?? current.permission,
        }, {
          category: normalized.category,
          type: normalized.type,
          summary: normalized.summary,
          metadata: { ...normalized.metadata, status: "WAITING_PERMISSION" },
          at: event.at,
        });
        return;
      }
      if (normalized.status === "RUNNING" && current.status === "WAITING_PERMISSION") {
        await this.options.store.transition(runId, "RUNNING", {
          permission: normalized.permission ?? current.permission,
        }, {
          category: normalized.category,
          type: normalized.type,
          summary: normalized.summary,
          metadata: { ...normalized.metadata, status: "RUNNING" },
          at: event.at,
        });
        return;
      }
      await this.options.store.appendEvent(runId, {
        category: normalized.category,
        type: normalized.type,
        summary: normalized.summary,
        metadata: { ...normalized.metadata, status: current.status },
        at: event.at,
      });
    } catch (error) {
      if (!(error instanceof RunTransitionError)) throw error;
    }
  }

  private async finalizeInspection(
    runId: string,
    inspection: NativeInspection,
    plan: RunPlan | null,
  ): Promise<void> {
    if (inspection.outcome === "succeeded") {
      await this.finalizeSucceeded(runId, inspection, plan);
      return;
    }
    if (inspection.outcome === "failed") {
      await this.settle(runId, "FAILED", {
        terminalReason: "native-failed",
        error: {
          code: "NATIVE_FAILED",
          message: "OpenCode reported that the native execution failed.",
          retryable: true,
        },
        limitation: "OpenCode reported a failed native outcome. Completed file changes are not undone.",
        usage: inspection.usage,
        model: inspection.model,
      }, {
        category: "error",
        type: "run.failed",
        summary: "OpenCode reported that the native execution failed.",
        metadata: { status: "FAILED" },
      });
      return;
    }
    if (inspection.outcome === "interrupted") {
      await this.settle(runId, "CANCELLED", {
        terminalReason: "native-interrupted",
        interruptAccepted: true,
        usage: inspection.usage,
        model: inspection.model,
        limitation: "The native session reported an interrupt. Completed file changes are not undone.",
      }, {
        category: "session",
        type: "run.cancelled",
        summary: "OpenCode confirmed that the native session was interrupted.",
        metadata: { status: "CANCELLED" },
      });
      return;
    }
    if (inspection.idle) {
      await this.markUnknown(runId, {
        code: "NATIVE_OUTCOME_MISSING",
        message: "The native session is idle but did not report a terminal outcome.",
        retryable: true,
      });
      return;
    }
    const current = await this.options.store.get(runId);
    if (current && !isSettledRunStatus(current.status)) {
      await this.options.store.transition(runId, "RUNNING", {}, {
        category: "session",
        type: "run.still-running",
        summary: "The native session is still running.",
        metadata: { status: "RUNNING" },
      });
    }
  }

  private async finalizeSucceeded(runId: string, inspection: NativeInspection, plan: RunPlan | null): Promise<void> {
    const current = await this.options.store.get(runId);
    if (!current || isTerminalRunStatus(current.status)) return;
    let run = current;
    if (current.status !== "VERIFYING") {
      run = await this.lock(runId, async () => {
        const fresh = await this.options.store.get(runId);
        if (!fresh || isTerminalRunStatus(fresh.status)) return fresh ?? current;
        if (fresh.status === "VERIFYING") return fresh;
        return this.options.store.transition(runId, "VERIFYING", {
          model: inspection.model,
          usage: inspection.usage,
        }, {
          category: "verification",
          type: "run.verifying",
          summary: "OpenCode finished. Collecting the diff and verification evidence.",
          metadata: { status: "VERIFYING" },
        });
      });
    }

    let diff: RunDiffFile[] = [];
    let diffError: unknown = null;
    try {
      diff = await this.options.driver.diff(inspection.sessionId);
    } catch (error) {
      diffError = error;
    }

    if (diff.length === 0) {
      const message = diffError
        ? `OpenCode finished, but the diff could not be read: ${redactString(errorMessage(diffError), 300)}`
        : "OpenCode finished without a file diff. Verification did not run because there was no change to check.";
      await this.settle(run.id, "FAILED", {
        terminalReason: "no-diff",
        diff: [],
        verification: {
          checkId: "CK-06",
          result: "NOT_RUN",
          fingerprint: "",
          observedAt: this.now().toISOString(),
          summary: "No file change was available to verify.",
          limitation: message,
        },
        usage: inspection.usage,
        model: inspection.model,
        limitation: message,
      }, {
        category: "verification",
        type: "run.no-diff",
        summary: message,
        metadata: { status: "FAILED" },
        evidence: run.sessionId ? [{ kind: "session", reference: run.sessionId }] : [],
      });
      return;
    }

    let verification: RunVerification;
    try {
      verification = await this.options.verify({ workspace: plan?.workspace ?? "", diff });
    } catch (error) {
      verification = {
        checkId: "CK-06",
        result: "INCONCLUSIVE",
        fingerprint: "",
        observedAt: this.now().toISOString(),
        summary: "The verification step could not run.",
        limitation: redactString(errorMessage(error), 1_000),
      };
    }

    const passed = verification.result === "PASS";
    const status: RunStatus = passed ? "SUCCEEDED" : "FAILED";
    const limitation = passed
      ? null
      : verification.limitation ?? "The observed verification did not pass. The diff is retained as evidence.";
    await this.settle(run.id, status, {
      terminalReason: passed ? "completed" : "verification-failed",
      diff,
      verification,
      usage: inspection.usage,
      model: inspection.model,
      limitation,
      evidence: [
        ...(run.sessionId ? [{ kind: "session", reference: run.sessionId }] : []),
        { kind: "verification", reference: `CK-06:${verification.result}` },
        ...diff.slice(0, 20).map((file) => ({ kind: "diff", reference: file.file })),
      ],
    }, {
      category: "verification",
      type: passed ? "run.succeeded" : "run.verification-failed",
      summary: passed
        ? `Maker finished. ${diff.length} file${diff.length === 1 ? "" : "s"} changed and CK-06 passed.`
        : `Maker finished with ${diff.length} file${diff.length === 1 ? "" : "s"} changed, but CK-06 ${verification.result.toLowerCase()}.`,
      metadata: { status, check: verification.result, files: diff.length },
      evidence: diff.slice(0, 10).map((file) => ({ kind: "diff", reference: file.file })),
    });
  }

  private async settle(
    runId: string,
    status: RunStatus,
    patch: Partial<RunRecord>,
    event: RunEventInput,
  ): Promise<RunRecord | null> {
    const settled = await this.lock(runId, async () => {
      const current = await this.options.store.get(runId);
      if (!current) return null;
      if (isTerminalRunStatus(current.status)) return current;
      const now = this.now();
      const started = current.createdAt;
      const transition = await this.options.store.transition(runId, status, {
        ...patch,
        completedAt: patch.completedAt ?? now.toISOString(),
        durationMs: patch.durationMs ?? Math.max(0, now.getTime() - new Date(started).getTime()),
      }, {
        ...event,
        metadata: { ...event.metadata, status },
      });
      if (this.plans.has(runId) && isTerminalRunStatus(status)) this.plans.delete(runId);
      return transition;
    });
    if (settled && isTerminalRunStatus(settled.status)) {
      await this.options.onSettled(settled);
    }
    return settled;
  }

  private async markUnknown(runId: string, error: { code: string; message: string; retryable: boolean }): Promise<RunRecord | null> {
    const settled = await this.lock(runId, async () => {
      const current = await this.options.store.get(runId);
      if (!current) return null;
      if (isSettledRunStatus(current.status)) return current;
      return this.options.store.transition(runId, "UNKNOWN", {
        terminalReason: "unknown",
        error,
        limitation: error.message,
      }, {
        category: "error",
        type: "run.unknown",
        summary: error.message,
        metadata: { status: "UNKNOWN", code: error.code },
      });
    });
    if (settled && settled.status === "UNKNOWN") await this.options.onSettled(settled);
    return settled;
  }

  private async handleError(
    runId: string,
    error: unknown,
    context: { workSent: boolean; sessionId: string | null },
  ): Promise<void> {
    const classified = classifyNativeError(error);
    if (context.workSent) {
      await this.markUnknown(runId, {
        ...classified,
        message: `${classified.message} The native session was retained; the work was not repeated.`,
      });
      return;
    }
    await this.settle(runId, "FAILED", {
      terminalReason: classified.code.toLowerCase(),
      error: classified,
      limitation: context.sessionId
        ? "No work was confirmed as sent. The native session was retained for inspection."
        : "No native session was created. No work was sent.",
    }, {
      category: "error",
      type: "run.failed",
      summary: classified.message,
      metadata: { status: "FAILED", code: classified.code },
    });
  }

  async cancel(runId: string, actionId: string): Promise<RunRecord> {
    const run = await this.options.store.get(runId);
    if (!run) throw new RunConflictError("That run was not found.");
    if (isTerminalRunStatus(run.status)) return run;
    if (run.cancelActionId && run.cancelActionId !== actionId) {
      throw new RunConflictError("A different cancellation action was already used for this run.");
    }
    if (run.cancelRequestedAt) return run;

    await this.options.store.update(runId, (current) => ({
      ...current,
      cancelRequestedAt: this.now().toISOString(),
      cancelActionId: actionId,
    }));
    await this.options.store.appendEvent(runId, {
      category: "run",
      type: "run.cancel-requested",
      summary: "Cancellation requested. Waiting for OpenCode's native interrupt outcome.",
      metadata: { status: run.status },
    });

    if (!run.sessionId) {
      await this.settle(runId, "CANCELLED", {
        terminalReason: "cancelled-before-session",
        limitation: "The run was cancelled before a native session started. No work was sent.",
      }, {
        category: "run",
        type: "run.cancelled",
        summary: "Run cancelled before any native work was sent.",
        metadata: { status: "CANCELLED" },
      });
      return (await this.options.store.get(runId)) ?? run;
    }

    let interrupt: { interrupted: boolean };
    try {
      interrupt = await this.options.driver.interrupt(run.sessionId);
    } catch (error) {
      const classified = classifyNativeError(error);
      await this.markUnknown(runId, {
        ...classified,
        message: `OpenCode did not confirm the interrupt: ${classified.message} The native session was retained.`,
      });
      return (await this.options.store.get(runId)) ?? run;
    }
    await this.options.store.update(runId, (current) => ({ ...current, interruptAccepted: interrupt.interrupted }));
    await this.options.store.appendEvent(runId, {
      category: "run",
      type: interrupt.interrupted ? "run.interrupt-accepted" : "run.interrupt-not-accepted",
      summary: interrupt.interrupted
        ? "OpenCode accepted the native interrupt. Confirming the terminal outcome."
        : "OpenCode did not report an active interrupt. Checking the native outcome.",
      metadata: { status: (await this.options.store.get(runId))?.status ?? run.status, interrupted: interrupt.interrupted },
    });

    const deadline = Date.now() + this.cancelObserveMs;
    while (Date.now() < deadline) {
      await sleep(Math.min(this.pollIntervalMs, 100));
      const inspection = await this.safeInspect(run.sessionId);
      if (inspection?.outcome) {
        await this.finalizeInspection(runId, inspection, this.plans.get(runId) ?? null);
        const settled = await this.options.store.get(runId);
        if (settled) return settled;
      }
    }

    const latest = await this.options.store.get(runId);
    if (latest && isSettledRunStatus(latest.status)) return latest;
    await this.markUnknown(runId, {
      code: interrupt.interrupted ? "CANCEL_OUTCOME_UNKNOWN" : "INTERRUPT_NOT_OBSERVED",
      message: interrupt.interrupted
        ? "OpenCode accepted the interrupt, but no terminal outcome was observed. The native session is retained; this run is not marked cancelled."
        : "OpenCode did not accept the interrupt and no terminal outcome was observed. The native session is retained.",
      retryable: false,
    });
    return (await this.options.store.get(runId)) ?? run;
  }

  async reconcile(runId: string): Promise<RunRecord> {
    const run = await this.options.store.get(runId);
    if (!run) throw new RunConflictError("That run was not found.");
    if (isTerminalRunStatus(run.status)) return run;

    if (!run.sessionId) {
      await this.settle(runId, "FAILED", {
        terminalReason: "no-native-session",
        error: {
          code: "NO_NATIVE_SESSION",
          message: "No native session was persisted for this run.",
          retryable: true,
        },
        limitation: "No work was confirmed as sent. Start a new run after checking the saved state.",
      }, {
        category: "error",
        type: "run.failed",
        summary: "No native session was persisted, so there is nothing to reconcile. No work was sent.",
        metadata: { status: "FAILED", code: "NO_NATIVE_SESSION" },
      });
      return (await this.options.store.get(runId)) ?? run;
    }

    if (run.status !== "UNKNOWN") {
      await this.options.store.transition(runId, "UNKNOWN", {
        reconciledAt: this.now().toISOString(),
        limitation: "Reconciliation requested. The app is checking the saved native session without retrying work.",
      }, {
        category: "session",
        type: "run.reconciling",
        summary: "Checking the saved native session. No work was repeated.",
        metadata: { status: "UNKNOWN" },
      });
    }

    let inspection: NativeInspection;
    try {
      inspection = await this.options.driver.inspect(run.sessionId);
    } catch (error) {
      const classified = classifyNativeError(error);
      await this.options.store.update(runId, (current) => ({
        ...current,
        reconciledAt: this.now().toISOString(),
        error: classified,
        limitation: "Reconciliation could not reach the saved native session. It remains unknown; no work was repeated.",
      }));
      await this.options.store.appendEvent(runId, {
        category: "error",
        type: "run.reconcile-failed",
        summary: "Reconciliation could not reach OpenCode. The saved session reference remains.",
        metadata: { status: "UNKNOWN", code: classified.code },
      });
      return (await this.options.store.get(runId)) ?? run;
    }

    await this.options.store.update(runId, (current) => ({
      ...current,
      reconciledAt: this.now().toISOString(),
      model: inspection.model ?? current.model,
      usage: inspection.usage,
    }));

    if (inspection.outcome) {
      await this.finalizeInspection(runId, inspection, this.plans.get(runId) ?? null);
    } else if (!inspection.idle) {
      await this.options.store.transition(runId, "RUNNING", {}, {
        category: "session",
        type: "run.reconciled-running",
        summary: "The saved native session is still running. It was not started again.",
        metadata: { status: "RUNNING" },
      });
      void this.watchReconciled(runId, run.sessionId, this.plans.get(runId) ?? null);
    } else {
      await this.options.store.appendEvent(runId, {
        category: "session",
        type: "run.reconcile-unknown",
        summary: "OpenCode is idle but reports no outcome. The run remains unknown and was not repeated.",
        metadata: { status: "UNKNOWN" },
      });
    }
    return (await this.options.store.get(runId)) ?? run;
  }

  private async watchReconciled(runId: string, sessionId: string, plan: RunPlan | null): Promise<void> {
    const controller = new AbortController();
    this.controllers.set(runId, controller);
    try {
      const follow = this.options.driver.follow(
        sessionId,
        (event) => void this.onNativeEvent(runId, event),
        controller.signal,
      );
      let timedOut = false;
      const timer = sleep(this.timeoutMs).then(() => {
        timedOut = true;
      });
      await Promise.race([
        follow.catch(() => undefined),
        timer,
      ]);
      if (timedOut) {
        await this.markUnknown(runId, {
          code: "NATIVE_TIMEOUT",
          message: "The reconciled native session did not finish before the timeout. The session reference was retained.",
          retryable: true,
        });
        return;
      }
      const inspection = await this.safeInspect(sessionId);
      if (inspection) await this.finalizeInspection(runId, inspection, plan);
    } finally {
      this.controllers.delete(runId);
    }
  }

  async recover(): Promise<RunRecord[]> {
    const runs = await this.options.store.listNonTerminal();
    const results: RunRecord[] = [];
    for (const run of runs) {
      if (!run.sessionId) {
        await this.settle(run.id, "FAILED", {
          terminalReason: "interrupted-by-restart",
          error: {
            code: "INTERRUPTED_BY_RESTART",
            message: "The server restarted before a native session was saved.",
            retryable: true,
          },
          limitation: "No native session was saved, so no work was confirmed as sent. Start a new run.",
        }, {
          category: "error",
          type: "run.restart-failed",
          summary: "Server restart interrupted the run before a native session was saved. No work was sent.",
          metadata: { status: "FAILED" },
        });
        const settled = await this.options.store.get(run.id);
        if (settled) results.push(settled);
        continue;
      }
      await this.options.store.transition(run.id, "UNKNOWN", {
        reconciledAt: this.now().toISOString(),
        limitation: "The server restarted. The saved native session is being reconciled; work was not repeated.",
      }, {
        category: "run",
        type: "run.restart-reconciling",
        summary: "Server restart detected. Reconciling the saved native session without repeating work.",
        metadata: { status: "UNKNOWN" },
      });
      await this.options.onSettled((await this.options.store.get(run.id))!);
      results.push(await this.reconcile(run.id));
    }
    return results;
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? "Unknown error");
}

function isSettledRunStatusSafe(plans: Map<string, RunPlan>, runId: string): boolean {
  return plans.has(runId);
}

