async function withDeadline<T>(work: Promise<T>, milliseconds: number): Promise<{ timedOut: boolean; value?: T }> {
  let timer: NodeJS.Timeout | undefined;
  try {
    const value = await Promise.race([
      work,
      new Promise<"timeout">((resolve) => {
        timer = setTimeout(() => resolve("timeout"), milliseconds);
      }),
    ]);
    return value === "timeout" ? { timedOut: true } : { timedOut: false, value };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

