private async markUnknown(runId: string, error: { code: string; message: string; retryable: boolean }): Promise<RunRecord | null> {
  let changed = false;
  const settled = await this.lock(runId, async () => {
    const current = await this.options.store.get(runId);
    if (!current) return null;
    if (isSettledRunStatus(current.status)) return current;
    changed = true;
    return this.options.store.transition(runId, "UNKNOWN", {
      terminalReason: "unknown",
      error,
      limitation: error.message,
    }, {
      category: "error",
      type: "run.unknown",
      summary: error.message,
      metadata: { status: "UNKNOWN", code: error.code },
    });
  });
  if (settled && changed) await this.options.onSettled(settled);
  return settled;
}

