import { createHash, randomUUID } from "node:crypto";
import {
  isTerminalRunStatus,
  type RunDiffFile,
  type RunRecord,
  type RunVerification,
} from "../../shared/runs.ts";
import { buildInstructions } from "../experience/instructions.ts";
import { runApprovedNodeCheck } from "../experience/node-check.ts";
import { ExperienceFailure } from "../experience/service.ts";
import type { NativeRunDriver } from "../opencode/run-driver.ts";
import { RevisionConflict } from "../store/atomic-project-store.ts";
import { payloadHash, refreshNextAction, type Project } from "../workflow/model.ts";
import { WorkflowService } from "../workflow/service.ts";
import { WorkflowConflict } from "../workflow/transitions.ts";
import { RunCoordinator } from "./coordinator.ts";
import { redactString } from "./redaction.ts";
import { RunStore, hashPayload } from "./store.ts";

export interface MakerRunServiceOptions {
  workflow: WorkflowService;
  runStore: RunStore;
  driver: NativeRunDriver;
  demoWorkspace: string;
  promptRoot?: string;
  timeoutMs?: number;
  cancelObserveMs?: number;
  pollIntervalMs?: number;
}

export interface StartedRun {
  run: RunRecord;
  project: Project;
  duplicate: boolean;
}

export class MakerRunService {
  readonly coordinator: RunCoordinator;

  constructor(private readonly options: MakerRunServiceOptions) {
    this.coordinator = new RunCoordinator({
      driver: options.driver,
      store: options.runStore,
      timeoutMs: options.timeoutMs,
      cancelObserveMs: options.cancelObserveMs,
      pollIntervalMs: options.pollIntervalMs,
      verify: async ({ workspace, diff }) => verifyMaker(workspace, diff),
      onSettled: (run) => this.commitRun(run),
    });
  }

  async start(actionId: string, expectedRevision: number): Promise<StartedRun> {
    const payload = { intent: "maker" };
    const existing = await this.options.runStore.findByActionId(actionId);
    if (existing) {
      if (existing.payloadHash !== hashPayload(payload)) {
        throw new RevisionConflict("Action ID was already used with a different payload.");
      }
      return { run: existing, project: await this.options.workflow.get(), duplicate: true };
    }

    const project = await this.options.workflow.get();
    if (project.revision !== expectedRevision) {
      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${project.revision}.`);
    }
    if (project.makerScope.status !== "GRANTED" || !project.makerScope.statement) {
      throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
    }
    const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
    if (unresolved.length > 0) {
      throw new ExperienceFailure(
        `${unresolved.length} plan section(s) still need approval before Maker can run.`,
        "PLAN_NOT_APPROVED",
        409,
        false,
      );
    }
    const active = await this.options.runStore.activeForProject(project.id);
    if (active) {
      throw new ExperienceFailure(
        `Run ${active.id} is already ${active.status.toLowerCase()}. Wait for it to finish or reconcile it first.`,
        "RUN_IN_PROGRESS",
        409,
        false,
      );
    }
    if (!this.coordinator.hasCapacity()) {
      throw new ExperienceFailure("The run coordinator is busy. Wait for the current run to finish.", "RUN_QUEUE_FULL", 503, true);
    }

    const prompt = await buildInstructions("maker", project, project.makerScope.statement, this.options.promptRoot);
    const run = await this.options.runStore.create({
      projectId: project.id,
      actionId,
      payloadHash: hashPayload(payload),
      workspace: this.options.demoWorkspace,
    });
    this.coordinator.enqueue(run.id, { prompt, workspace: this.options.demoWorkspace });
    return { run, project, duplicate: false };
  }

  async latest(projectId?: string): Promise<RunRecord | null> {
    return this.options.runStore.latest(projectId);
  }

  async get(runId: string): Promise<RunRecord | null> {
    return this.options.runStore.get(runId);
  }

  async cancel(runId: string, actionId: string): Promise<{ run: RunRecord; project: Project }> {
    const run = await this.coordinator.cancel(runId, actionId);
    return { run, project: await this.options.workflow.get() };
  }

  async reconcile(runId: string): Promise<{ run: RunRecord; project: Project }> {
    const run = await this.coordinator.reconcile(runId);
    return { run, project: await this.options.workflow.get() };
  }

  async recover(): Promise<RunRecord[]> {
    return this.coordinator.recover();
  }

  subscribe(runId: string, listener: Parameters<RunStore["subscribe"]>[1]): () => void {
    return this.options.runStore.subscribe(runId, listener);
  }

  private async commitRun(run: RunRecord): Promise<void> {
    if (!["SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"].includes(run.status)) return;
    const project = await this.options.workflow.get();
    if (project.id !== run.projectId) return;
    const actionId = `run:${run.id}:${run.status}`;
    try {
      await this.options.workflow.commit(actionId, { runId: run.id, status: run.status }, (current) => {
        const next = structuredClone(current);
        if (!next.runIds.includes(run.id)) next.runIds.push(run.id);
        const existing = next.operations.find((operation) => operation.runId === run.id);
        const result = runResult(run);
        const operation = existing ?? {
          id: randomUUID(),
          kind: "maker" as const,
          payloadHash: payloadHash({ intent: "maker" }),
          runId: run.id,
          nativeSessionId: run.sessionId,
          nativeMessageId: run.messageId,
          status: "QUEUED" as const,
          result: null,
        };
        operation.status = run.status === "UNKNOWN" ? "UNKNOWN" : run.status;
        operation.nativeSessionId = run.sessionId ?? operation.nativeSessionId;
        operation.nativeMessageId = run.messageId ?? operation.nativeMessageId;
        operation.result = result;
        if (!existing) next.operations.push(operation);

        if (run.sessionId) rememberMakerSession(next, run.sessionId);
        if (run.verification) {
          const reference = run.sessionId ?? run.id;
          const evidence = next.evidence.find((item) => item.checkId === run.verification!.checkId && item.nativeResultReference === reference);
          const payload = {
            checkId: run.verification.checkId,
            nativeResultReference: reference,
            testedFingerprint: run.verification.fingerprint,
            result: run.verification.result,
            observedAt: run.verification.observedAt,
            limitation: run.verification.limitation,
          };
          if (evidence) Object.assign(evidence, payload);
          else next.evidence.push({ id: randomUUID(), ...payload });
          const capability = next.capabilities.find((item) => item.id === "node-check");
          if (capability) {
            capability.availability = "available";
            capability.observedOutcome = run.verification.result;
          }
        }
        if (run.diff.length) {
          const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
          if (inspection) {
            inspection.availability = "available";
            inspection.observedOutcome = redactString(run.diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n"), 1_000);
          }
        }
        rememberMakerTranscript(next, result);
        const refreshed = refreshNextAction(next);
        if (run.status === "UNKNOWN") refreshed.nextAction = "Reconcile the saved Maker session before retrying";
        if (run.status === "FAILED") refreshed.nextAction = "Inspect the failure and retry the approved Maker unit";
        if (run.status === "CANCELLED") refreshed.nextAction = "Run the approved Maker unit again when ready";
        return refreshed;
      });
    } catch (error) {
      if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
        // The run itself is durable even if the project snapshot is being edited.
        // A later reconciliation or refresh can retry this projection.
        return;
      }
      throw error;
    }
  }
}

export async function verifyMaker(workspace: string, diff: RunDiffFile[]): Promise<RunVerification> {
  if (diff.length === 0) {
    return {
      checkId: "CK-06",
      result: "NOT_RUN",
      fingerprint: "",
      observedAt: new Date().toISOString(),
      summary: "No file change was available to verify.",
      limitation: "Verification only runs after an observed native diff.",
    };
  }
  if (!workspace) {
    return {
      checkId: "CK-06",
      result: "INCONCLUSIVE",
      fingerprint: "",
      observedAt: new Date().toISOString(),
      summary: "The demo workspace path was not available after reconciliation.",
      limitation: "The diff is retained, but the Node check could not be run in this process.",
    };
  }
  const check = await runApprovedNodeCheck(workspace);
  const output = redactString(check.output, 2_000);
  const passed = check.code === 0;
  return {
    checkId: "CK-06",
    result: passed ? "PASS" : "FAIL",
    fingerprint: createHash("sha256").update(check.output).digest("hex"),
    observedAt: new Date().toISOString(),
    summary: `Node check exit ${check.code ?? "unavailable"}. ${output}`,
    limitation: passed ? null : "The native edit did not leave a passing Node test.",
  };
}

function runResult(run: RunRecord): string {
  const diff = run.diff.length
    ? run.diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
    : "No file diff was observed.";
  const check = run.verification
    ? `CK-06 ${run.verification.result}. ${run.verification.summary}`
    : "No verification result was recorded.";
  const limit = run.limitation ? `\nLimitation: ${run.limitation}` : "";
  return redactString(`${diff}\n\n${check}${limit}`, 8_000);
}

function rememberMakerSession(project: Project, sessionId: string): void {
  const existing = project.nativeSessions.find((item) => item.role === "maker");
  if (existing) existing.sessionId = sessionId;
  else project.nativeSessions.push({ role: "maker", sessionId });
}

function rememberMakerTranscript(project: Project, text: string): void {
  const previous = project.transcript.at(-1);
  if (previous?.spirit === "maker" && previous.text === text) return;
  project.transcript.push({
    id: randomUUID(),
    spirit: "maker",
    text,
    createdAt: new Date().toISOString(),
  });
  if (project.transcript.length > 80) project.transcript.splice(0, project.transcript.length - 80);
}

export function isRunFinished(run: RunRecord): boolean {
  return isTerminalRunStatus(run.status) || run.status === "UNKNOWN";
}

import type { Context } from "hono";
import { streamSSE } from "hono/streaming";
import { isSettledRunStatus, type RunStatus } from "../../shared/runs.ts";
import type { MakerRunService } from "./maker-run-service.ts";

export interface RunEventStreamOptions {
  sessionToken: string;
  heartbeatMs: number;
}

export function parseCursor(context: Context): number {
  const query = context.req.query("after") ?? context.req.query("lastEventId") ?? context.req.header("last-event-id");
  if (!query) return 0;
  const parsed = Number(query);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : 0;
}

export async function streamRunEvents(
  context: Context,
  service: MakerRunService,
  runId: string,
  options: RunEventStreamOptions,
): Promise<Response> {
  const provided = context.req.query("token") ?? context.req.header("x-ub-session-token");
  if (provided !== options.sessionToken) {
    return context.json({ code: "INVALID_SESSION", message: "A valid local browser session token is required for the event stream.", retryable: false }, 403);
  }
  const initial = await service.get(runId);
  if (!initial) {
    return context.json({ code: "RUN_NOT_FOUND", message: "That run was not found.", retryable: false }, 404);
  }
  const after = parseCursor(context);

  return streamSSE(context, async (stream) => {
    let cursor = after;
    let finished = false;
    let finish: () => void = () => undefined;
    const done = new Promise<void>((resolve) => {
      finish = resolve;
    });

    const write = async (event: { seq: number; [key: string]: unknown }) => {
      if (event.seq <= cursor) return;
      await stream.writeSSE({
        id: String(event.seq),
        event: "run-event",
        data: JSON.stringify(event),
      });
      cursor = event.seq;
    };

    const snapshot = async (source: "initial" | "resync") => {
      const latest = await service.get(runId) ?? initial;
      await stream.writeSSE({
        event: "snapshot",
        data: JSON.stringify({
          run: latest,
          lastEventSeq: latest.lastEventSeq,
          source,
        }),
        retry: 2_000,
      });
      return latest;
    };

    const writeClose = async (status: RunStatus) => {
      await stream.writeSSE({
        event: "close",
        data: JSON.stringify({ status, lastEventSeq: cursor }),
      }).catch(() => undefined);
    };

    try {
      const first = await snapshot(after === 0 ? "initial" : "resync");
      const earliest = first.events[0]?.seq ?? 0;
      if (after > first.lastEventSeq || (after > 0 && earliest > 0 && after < earliest - 1)) {
        await stream.writeSSE({
          event: "resync",
          data: JSON.stringify({
            reason: after > first.lastEventSeq ? "cursor-ahead" : "cursor-expired",
            lastEventSeq: first.lastEventSeq,
          }),
        });
        cursor = 0;
      }
      for (const event of first.events) await write(event);

      // Subscribe before the final read so events appended during replay are
      // either written live or found by the second replay.
      const unsubscribe = service.subscribe(runId, (event) => {
        void write(event)
          .then(() => {
            const status = event.metadata.status;
            if (typeof status === "string" && isSettledRunStatus(status as RunStatus)) {
              finished = true;
              finish();
            }
          })
          .catch(() => {
            finished = true;
            finish();
          });
      });

      const latest = await service.get(runId) ?? first;
      for (const event of latest.events) await write(event);
      if (isSettledRunStatus(latest.status)) {
        await writeClose(latest.status);
        unsubscribe();
        await stream.close();
        return;
      }

      const heartbeat = setInterval(() => {
        void stream.writeSSE({
          event: "heartbeat",
          data: JSON.stringify({ at: new Date().toISOString(), lastEventSeq: cursor }),
        }).catch(() => {
          finished = true;
          finish();
        });
      }, Math.max(25, options.heartbeatMs));
      stream.onAbort(() => {
        finished = true;
        finish();
      });
      await done;
      clearInterval(heartbeat);
      unsubscribe();
      if (!finished) await writeClose(latest.status);
      await stream.close();
    } catch {
      finish();
      try {
        await stream.close();
      } catch {
        // The browser already closed the stream.
      }
    }
  });
}

