export type RunStatus =
  | "QUEUED"
  | "CONNECTING"
  | "RUNNING"
  | "WAITING_PERMISSION"
  | "VERIFYING"
  | "SUCCEEDED"
  | "FAILED"
  | "CANCELLED"
  | "UNKNOWN";

export interface RunEvent {
  version: 1;
  seq: number;
  runId: string;
  at: string;
  category: "run" | "connection" | "session" | "model" | "tool" | "permission" | "file" | "verification" | "evidence" | "error" | "heartbeat";
  type: string;
  summary: string;
  metadata: Record<string, unknown>;
  evidence: Array<{ kind: string; reference: string }>;
}

export interface RunRecord {
  schemaVersion: 1;
  id: string;
  projectId: string;
  actionId: string;
  status: RunStatus;
  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  completedAt: string | null;
  durationMs: number | null;
  sessionId: string | null;
  messageId: string | null;
  model: string | null;
  workspace: string;
  lastEventSeq: number;
  lastSummary: string;
  cancelRequestedAt: string | null;
  interruptAccepted: boolean | null;
  reconciledAt: string | null;
  terminalReason: string | null;
  error: { code: string; message: string; retryable: boolean } | null;
  permission: { requestId: string | null; action: string | null; resources: string[]; status: "requested" | "replied" } | null;
  diff: Array<{ file: string; status: "added" | "deleted" | "modified"; additions: number; deletions: number }>;
  verification: {
    checkId: "CK-06";
    result: "PASS" | "FAIL" | "NOT_RUN" | "INCONCLUSIVE";
    fingerprint: string;
    observedAt: string;
    summary: string;
    limitation: string | null;
  } | null;
  usage: {
    cost: number | null;
    input: number | null;
    output: number | null;
    reasoning: number | null;
    cacheRead: number | null;
    cacheWrite: number | null;
  } | null;
  limitation: string | null;
  evidence: Array<{ kind: string; reference: string }>;
  events: RunEvent[];
}

export interface WorkshopProject {
  revision: number;
  stage: "ORACLE" | "ARCHITECT" | "MAKER" | "WITNESS";
  currentSectionId: string | null;
  nextAction: string;
  product: { status: "NONE" | "PROPOSED" | "APPROVED"; proposal: string | null; openQuestions: string[] };
  makerScope: { status: "NONE" | "GRANTED"; statement: string | null };
  sections: Array<{
    id: string;
    title: string;
    order: number;
    content: string;
    version: number;
    hash: string;
    status: "NOT_STARTED" | "DRAFT" | "APPROVED" | "STALE";
  }>;
  transcript: Array<{ id: string; spirit: string; text: string }>;
  operations: Array<{ id: string; kind: string; runId: string | null; status: string; result: string | null; nativeSessionId: string | null }>;
  capabilities: Array<{
    id: string;
    purpose: string;
    nativeMapping: string;
    availability: string;
    permission: string;
    observedOutcome: string | null;
  }>;
  witnessDrafts: Array<{ id: string; title: string; content: string }>;
  evidence: Array<{ id: string; checkId: string; result: string; limitation: string | null }>;
  runIds: string[];
}

export interface EngineStatus {
  available: boolean;
  serverVersion: string | null;
  modelAvailable: boolean;
  limitation: string | null;
}

export interface ActionResult {
  project: WorkshopProject;
  duplicate: boolean;
}

export interface RunActionResult {
  run: RunRecord;
  project: WorkshopProject;
  duplicate?: boolean;
}

export class ApiError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}

let sessionToken: string | null = null;

export async function localSessionToken(): Promise<string> {
  if (sessionToken) return sessionToken;
  const response = await fetch("/api/session");
  if (!response.ok) throw new ApiError("The local workshop session could not be opened.", "SESSION", true);
  const body = await response.json() as { token: string };
  sessionToken = REDACTED;
  return sessionToken;
}

async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
  const headers: Record<string, string> = {};
  if (init?.body) {
    headers["content-type"] = "application/json";
    headers["x-ub-session-token"] = await localSessionToken();
  }
  const response = await fetch(path, {
    method: init?.method ?? "GET",
    headers,
    body: init?.body ? JSON.stringify(init.body) : undefined,
  });
  const body = await response.json() as T & { message?: string; code?: string; retryable?: boolean };
  if (!response.ok) {
    throw new ApiError(body.message ?? "The workshop could not complete that action.", body.code ?? "REQUEST_FAILED", Boolean(body.retryable));
  }
  return body;
}

export function loadProject() {
  return request<WorkshopProject>("/api/project");
}

export async function loadEngine(): Promise<EngineStatus> {
  try {
    const response = await fetch("/api/engine");
    const body = await response.json() as Partial<EngineStatus>;
    if (typeof body.available === "boolean") {
      return {
        available: body.available,
        serverVersion: body.serverVersion ?? null,
        modelAvailable: Boolean(body.modelAvailable),
        limitation: body.limitation ?? null,
      };
    }
  } catch {
    // The status below is the visible recovery state.
  }
  return {
    available: false,
    serverVersion: null,
    modelAvailable: false,
    limitation: "OpenCode could not be reached from this workshop.",
  };
}

export function sendMessage(project: WorkshopProject, intent: "clarify" | "draft" | "question" | "witness", text: string) {
  return request<ActionResult>("/api/messages", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, intent, text },
  });
}

export function approveProduct(project: WorkshopProject) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "product" },
  });
}

export function grantScope(project: WorkshopProject, statement: string) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "maker-scope", statement },
  });
}

export function approveSection(project: WorkshopProject, version: number, hash: string, sectionId: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/approve`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, version, hash },
  });
}

export function reviseSection(project: WorkshopProject, sectionId: string, content: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/revisions`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, content },
  });
}

export function startMakerRun(project: WorkshopProject) {
  return request<RunActionResult>("/api/runs", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision },
  });
}

export async function loadLatestRun(): Promise<RunRecord | null> {
  const response = await request<{ run: RunRecord | null }>("/api/runs/latest");
  return response.run;
}

export async function loadRun(runId: string): Promise<RunRecord> {
  const response = await request<{ run: RunRecord }>(`/api/runs/${runId}`);
  return response.run;
}

export function cancelRun(runId: string, actionId = crypto.randomUUID()) {
  return request<RunActionResult>(`/api/runs/${runId}/cancel`, {
    method: "POST",
    body: { actionId, expectedRevision: 0 },
  });
}

export function reconcileRun(runId: string) {
  return request<RunActionResult>(`/api/runs/${runId}/reconcile`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: 0 },
  });
}

export async function runEventsUrl(runId: string, after: number): Promise<string> {
  const token = await localSessionToken();
  return `/api/runs/${runId}/events?after=${after}&token=${encodeURIComponent(token)}`;
}

export function loadExport() {
  return request<{ plan: string | null; unresolved: string[]; drafts: Array<{ title: string; content: string }>; limitation: string }>("/api/export");
}

import { useEffect, useRef, useState } from "react";
import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import {
  ApiError,
  approveProduct,
  approveSection,
  cancelRun,
  grantScope,
  loadEngine,
  loadExport,
  loadLatestRun,
  loadProject,
  loadRun,
  reconcileRun,
  reviseSection,
  runEventsUrl,
  sendMessage,
  startMakerRun,
  type EngineStatus,
  type RunEvent,
  type RunRecord,
  type RunStatus,
  type WorkshopProject,
} from "./api.ts";

const spirits = [
  ["ORACLE", "Oracle", Sparkles],
  ["ARCHITECT", "Architect", ScrollText],
  ["MAKER", "Maker", Hammer],
  ["WITNESS", "Witness", Eye],
] as const;

const activeStatuses: RunStatus[] = ["QUEUED", "CONNECTING", "RUNNING", "WAITING_PERMISSION", "VERIFYING"];

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [engine, setEngine] = useState<EngineStatus | null>(null);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [waitStartedAt, setWaitStartedAt] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const [run, setRun] = useState<RunRecord | null>(null);
  const [runEvents, setRunEvents] = useState<RunEvent[]>([]);
  const [runConnected, setRunConnected] = useState(false);
  const [runError, setRunError] = useState<string | null>(null);
  const [now, setNow] = useState(Date.now());
  const cursorRef = useRef(0);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    void Promise.all([loadProject(), loadEngine(), loadLatestRun()])
      .then(([loaded, native, latest]) => {
        setProject(loaded);
        setEngine(native);
        if (latest) {
          setRun(latest);
          setRunEvents(latest.events);
          cursorRef.current = latest.lastEventSeq;
          window.localStorage.setItem("ub.runId", latest.id);
        }
      })
      .catch((caught: unknown) => {
        setError(caught instanceof Error ? caught.message : "The workshop could not be loaded.");
      });
  }, []);

  useEffect(() => {
    if (!run) return;
    const timer = window.setInterval(() => setNow(Date.now()), 1_000);
    return () => window.clearInterval(timer);
  }, [run?.id]);

  useEffect(() => {
    if (!run || !activeStatuses.includes(run.status)) {
      setRunConnected(false);
      return;
    }
    let disposed = false;
    let source: EventSource | null = null;
    let poll: number | null = null;

    const mergeRun = (latest: RunRecord) => {
      setRun(latest);
      setRunEvents(latest.events);
      cursorRef.current = Math.max(cursorRef.current, latest.lastEventSeq);
      if (!activeStatuses.includes(latest.status)) {
        setRunConnected(false);
        source?.close();
      }
    };

    void runEventsUrl(run.id, cursorRef.current).then((url) => {
      if (disposed) return;
      source = new EventSource(url);
      source.addEventListener("open", () => setRunConnected(true));
      source.addEventListener("snapshot", (message) => {
        try {
          const data = JSON.parse((message as MessageEvent).data) as { run: RunRecord };
          mergeRun(data.run);
          setRunConnected(true);
        } catch {
          // A malformed frame is ignored; the poll below resynchronizes.
        }
      });
      source.addEventListener("resync", () => {
        void loadRun(run.id).then(mergeRun).catch(() => undefined);
      });
      source.addEventListener("run-event", (message) => {
        try {
          const event = JSON.parse((message as MessageEvent).data) as RunEvent;
          cursorRef.current = Math.max(cursorRef.current, event.seq);
          setRunEvents((current) => current.some((item) => item.seq === event.seq)
            ? current
            : [...current, event].sort((left, right) => left.seq - right.seq));
          const status = event.metadata.status;
          if (typeof status === "string") {
            setRun((current) => current ? { ...current, status: status as RunStatus, lastSummary: event.summary } : current);
          }
          if (typeof status === "string" && !activeStatuses.includes(status as RunStatus)) {
            setRunConnected(false);
            source?.close();
            void loadRun(run.id).then(mergeRun).catch(() => undefined);
          }
        } catch {
          // Ignore a single malformed frame; cursor recovery is handled by resync.
        }
      });
      source.addEventListener("heartbeat", () => {
        setRunConnected(true);
        setNow(Date.now());
      });
      source.addEventListener("close", () => {
        setRunConnected(false);
        source?.close();
        void loadRun(run.id).then(mergeRun).catch(() => undefined);
      });
      source.onerror = () => {
        setRunConnected(false);
        // EventSource reconnects with the cursor in the URL. The poll below also
        // repairs a missed terminal event without starting a second run.
      };
    }).catch((caught: unknown) => {
      setRunError(caught instanceof Error ? caught.message : "The live run stream could not be opened.");
    });

    poll = window.setInterval(() => {
      void loadRun(run.id).then(mergeRun).catch(() => undefined);
    }, 2_500);

    return () => {
      disposed = true;
      source?.close();
      if (poll !== null) window.clearInterval(poll);
    };
  }, [run?.id]);

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    setBusy(true);
    setWaitStartedAt(Date.now());
    setError(null);
    try {
      setProject((await work()).project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The current section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      setBusy(false);
      setWaitStartedAt(null);
    }
  }

  async function startMaker() {
    if (!project || busy || (run && activeStatuses.includes(run.status))) return;
    setBusy(true);
    setError(null);
    setRunError(null);
    try {
      const result = await startMakerRun(project);
      setProject(result.project);
      setRun(result.run);
      setRunEvents(result.run.events);
      cursorRef.current = result.run.lastEventSeq;
      window.localStorage.setItem("ub.runId", result.run.id);
    } catch (caught) {
      setRunError(caught instanceof ApiError ? caught.message : "The Maker run could not be started.");
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
    } finally {
      setBusy(false);
    }
  }

  async function cancelMaker() {
    if (!run || busy) return;
    setBusy(true);
    setRunError(null);
    try {
      const result = await cancelRun(run.id);
      setRun(result.run);
      setProject(result.project);
      setRunEvents(result.run.events);
    } catch (caught) {
      setRunError(caught instanceof ApiError ? caught.message : "Cancellation could not be requested.");
    } finally {
      setBusy(false);
    }
  }

  async function reconcileMaker() {
    if (!run || busy) return;
    setBusy(true);
    setRunError(null);
    try {
      const result = await reconcileRun(run.id);
      setRun(result.run);
      setProject(result.project);
      setRunEvents(result.run.events);
    } catch (caught) {
      setRunError(caught instanceof ApiError ? caught.message : "The saved native session could not be reconciled.");
    } finally {
      setBusy(false);
    }
  }

  if (!project) {
    return (
      <main className="workshop">
        <h1>Unfinished Business</h1>
        <p>{error ?? "The workshop is waking up."}</p>
      </main>
    );
  }

  const section = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const unknown = project.operations.find((item) => item.status === "UNKNOWN") ?? null;
  const header = project.stage === "ORACLE"
    ? "What's still haunting your to-do list?"
    : section
      ? `${section.title} — section ${section.order} of ${project.sections.length}`
      : project.nextAction;
  const runActive = Boolean(run && activeStatuses.includes(run.status));
  const waitSeconds = waitStartedAt ? Math.max(0, Math.round((now - waitStartedAt) / 1_000)) : 0;

  return (
    <>
      <a className="skip" href="#document">Skip to the working document</a>
      <main className="workshop">
        <nav className="stage-strip" aria-label="Spirits">
          {spirits.map(([id, label, Icon]) => {
            const done = stageOrder(project.stage) > stageOrder(id);
            return (
              <button key={id} type="button" className={done ? "stage done" : "stage"} aria-current={project.stage === id ? "step" : undefined} disabled>
                <Icon aria-hidden="true" size={18} />
                {label}
              </button>
            );
          })}
        </nav>
        <div className="frame">
          <aside className="side">
            <section className="panel">
              <h2>Outline</h2>
              <ol>
                {project.sections.map((item) => (
                  <li key={item.id} className={item.status === "STALE" ? "ghost" : undefined}>
                    {item.title} — {statusLabel(item)}
                  </li>
                ))}
              </ol>
            </section>
          </aside>
          <article className="document" id="document" aria-busy={busy || runActive}>
            <Lantern />
            <p className="eyebrow">{project.stage}</p>
            <h1>
              {header}
              {project.product.status === "APPROVED" && section?.status === "APPROVED" ? (
                <Seal label="Approved" reduceMotion={reduceMotion} />
              ) : null}
            </h1>
            <p className="status-line">Stopped here: {project.nextAction}</p>
            {engine && !engine.available ? (
              <p className="banner bad" role="status">
                {engine.limitation?.includes("fetch failed")
                  ? "OpenCode is not reachable on the configured loopback address."
                  : engine.limitation}{" "}
                Start OpenCode, then try again. No paid model will be used.
              </p>
            ) : null}
            {unknown && !runActive ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                {run?.status === "UNKNOWN" ? (
                  <button className="action secondary" type="button" disabled={busy} onClick={() => void reconcileMaker()}>Reconcile native session</button>
                ) : null}
              </p>
            ) : null}
            {waitStartedAt && busy ? (
              <p className="banner" role="status">
                Waiting for a response ({waitSeconds}s). The saved section is unchanged until it arrives.
              </p>
            ) : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}
            {runError ? <p className="banner bad" role="alert">{runError}</p> : null}

            {project.stage === "ORACLE" ? (
              <OraclePanel project={project} text={text} setText={setText} busy={busy} act={act} />
            ) : null}
            {project.stage === "ARCHITECT" && section ? (
              <ArchitectPanel
                project={project}
                section={section}
                change={change}
                setChange={setChange}
                text={text}
                setText={setText}
                busy={busy}
                act={act}
                reduceMotion={reduceMotion}
              />
            ) : null}
            {project.stage === "ARCHITECT" && !section ? (
              <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} act={act} />
            ) : null}
            {project.stage === "MAKER" ? (
              <MakerPanel
                project={project}
                run={run}
                busy={busy}
                starting={busy && !runActive}
                onStart={startMaker}
                onCancel={cancelMaker}
                onReconcile={reconcileMaker}
              />
            ) : null}
            {project.stage === "WITNESS" ? (
              <WitnessPanel project={project} text={text} setText={setText} busy={busy} act={act} exportNote={exportNote} setExportNote={setExportNote} />
            ) : null}
          </article>
          <aside className="side">
            {run ? (
              <RunInspector
                run={run}
                events={runEvents}
                connected={runConnected}
                now={now}
                busy={busy}
                onCancel={cancelMaker}
                onReconcile={reconcileMaker}
                onRetry={startMaker}
              />
            ) : null}
            <Activity project={project} />
          </aside>
        </div>
      </main>
    </>
  );
}

function OraclePanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const proposal = props.project.product.proposal;
  return (
    <>
      <p>Describe an idea you want to bring to life.</p>
      {proposal ? (
        <div className="reading prose">
          <h2>Oracle proposal</h2>
          <p>{proposal}</p>
          {props.project.product.openQuestions.length ? (
            <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
          ) : null}
        </div>
      ) : null}
      <label>
        Idea or question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        {proposal ? (
          <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => approveProduct(props.project))}>
            Approve product
          </button>
        ) : (
          <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
            Wake the Oracle
          </button>
        )}
        {proposal ? (
          <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
            Ask a question
          </button>
        ) : null}
      </div>
    </>
  );
}

function ArchitectPanel(props: {
