function RunInspector(props: {
  run: RunRecord;
  events: RunEvent[];
  connected: boolean;
  now: number;
  busy: boolean;
  onCancel: () => Promise<void>;
  onReconcile: () => Promise<void>;
  onRetry: () => Promise<void>;
}) {
  const active = activeStatuses.includes(props.run.status);
  const started = props.run.startedAt ?? props.run.createdAt;
  const elapsed = props.run.durationMs ?? Math.max(0, props.now - new Date(started).getTime());
  const last = props.events.at(-1);
  const permission = props.run.permission;
  return (
    <section className="panel inspector" aria-label="Run Inspector">
      <div className="inspector-head">
        <h2>Run Inspector</h2>
        <span className={`run-status ${props.run.status.toLowerCase()}`}>{statusLabelForRun(props.run.status)}</span>
      </div>
      <p className="meta">Run {shortId(props.run.id)} · {formatDuration(elapsed)} {active ? "elapsed" : "total"}</p>
      <p className="meta">{props.connected ? "Live event stream connected" : active ? "Reconnecting to the saved run stream" : "Event stream closed"}</p>
      <p className="run-last" aria-live="polite">
        {last ? `Last confirmed: ${last.summary}` : props.run.lastSummary}
      </p>
      {active ? (
        <p className="meta">
          Elapsed {formatDuration(elapsed)} · last confirmed event {last ? new Date(last.at).toLocaleTimeString() : "pending"}
        </p>
      ) : null}
      {props.run.sessionId ? <p className="meta">Session {props.run.sessionId}{props.run.model ? ` · ${props.run.model}` : ""}</p> : <p className="meta">No native session saved yet.</p>}
      {permission?.status === "requested" ? (
        <p className="banner">Waiting for a native permission: {permission.action ?? "action"}.</p>
      ) : null}
      {props.run.error ? (
        <p className="banner bad" role="status">
          {props.run.error.message}
          {props.run.error.code === "AUTHENTICATION_FAILED" ? " Repair OpenCode authentication, then start a new run." : ""}
        </p>
      ) : null}
      {props.run.limitation ? <p className="banner">{props.run.limitation}</p> : null}

      <div className="actions">
        {active ? <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.onCancel()}>Cancel native run</button> : null}
        {props.run.status === "UNKNOWN" ? <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.onReconcile()}>Reconcile saved session</button> : null}
        {!active && props.run.status !== "SUCCEEDED" ? <button className="action" type="button" disabled={props.busy} onClick={() => void props.onRetry()}>Start a new run</button> : null}
      </div>

      {props.run.diff.length ? (
        <section className="inspector-section">
          <h3>File changes</h3>
          <ul>
            {props.run.diff.map((file) => (
              <li key={`${file.status}-${file.file}`}>
                <span className="meta">{file.status}</span> {file.file} <span className="meta">+{file.additions}/-{file.deletions}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {props.run.verification ? (
        <section className="inspector-section">
          <h3>Verification</h3>
          <p>{props.run.verification.checkId}: {props.run.verification.result}</p>
          <p className="prose">{props.run.verification.summary}</p>
          {props.run.verification.fingerprint ? <p className="meta">Fingerprint {props.run.verification.fingerprint.slice(0, 16)}…</p> : null}
        </section>
      ) : null}

      {props.run.usage ? (
        <section className="inspector-section">
          <h3>Usage</h3>
          <p className="meta">
            Cost {props.run.usage.cost ?? "unreported"} · in {props.run.usage.input ?? "?"} · out {props.run.usage.output ?? "?"}
          </p>
        </section>
      ) : null}

      <section className="inspector-section">
        <h3>Activity</h3>
        {props.events.length === 0 ? <p>No event recorded yet.</p> : (
          <ol className="timeline">
            {props.events.slice(-30).map((event) => (
              <li key={event.seq}>
                <span className="meta">{event.category} · {new Date(event.at).toLocaleTimeString()}</span>
                <div>{event.summary}</div>
              </li>
            ))}
          </ol>
        )}
      </section>
      {props.run.evidence.length ? (
        <section className="inspector-section">
          <h3>Evidence</h3>
          <ul>
            {props.run.evidence.map((item) => <li key={`${item.kind}:${item.reference}`} className="meta">{item.kind}: {item.reference}</li>)}
          </ul>
        </section>
      ) : null}
    </section>
  );
}

function Activity({ project }: { project: WorkshopProject }) {
  const latest = [...project.operations].reverse().slice(0, 4);
  return (
    <>
      <section className="panel">
        <h2>Activity</h2>
        {latest.length === 0 ? <p>No native run yet.</p> : (
          <ul>
            {latest.map((item) => (
              <li key={item.id}>
                <span className="meta">{item.kind} · {item.status}</span>
                <div className="evidence">{(item.result ?? "No result recorded.").slice(0, 280)}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section className="panel">
        <h2>Evidence</h2>
        {project.evidence.length === 0 ? <p>No check has been observed.</p> : (
          <ul>
            {project.evidence.map((item) => (
              <li key={item.id}>{item.checkId}: {item.result}{item.limitation ? ` — ${item.limitation}` : ""}</li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function Seal({ label, reduceMotion }: { label: string; reduceMotion: boolean | null }) {
  if (reduceMotion) return <span className="seal">{label}</span>;
  return <motion.span className="seal" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>{label}</motion.span>;
}

function Lantern() {
  return (
    <svg className="lantern" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="12" y="3" width="8" height="3" rx="1" fill="#f4b66c" />
      <path d="M10 8h12l-1 16H11L10 8z" fill="#252031" stroke="#f4b66c" />
      <circle className="flame" cx="16" cy="16" r="3" fill="#f4b66c" />
    </svg>
  );
}

function statusLabel(section: WorkshopProject["sections"][number]): string {
  if (section.status === "DRAFT") return `Draft v${section.version}`;
  if (section.status === "NOT_STARTED") return "Not started";
  if (section.status === "APPROVED") return "Approved";
  return "Stale";
}

function statusLabelForRun(status: RunStatus): string {
  if (status === "WAITING_PERMISSION") return "Waiting for permission";
  if (status === "QUEUED") return "Queued";
  if (status === "CONNECTING") return "Connecting";
  if (status === "RUNNING") return "Running";
  if (status === "VERIFYING") return "Verifying";
  if (status === "SUCCEEDED") return "Succeeded";
  if (status === "FAILED") return "Failed";
  if (status === "CANCELLED") return "Cancelled";
  return "Unknown";
}

function shortId(id: string): string {
  return id.slice(0, 8);
}

function formatDuration(milliseconds: number): string {
  const seconds = Math.max(0, Math.round(milliseconds / 1_000));
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${seconds % 60}s`;
}

function stageOrder(stage: WorkshopProject["stage"]): number {
  return spirits.findIndex(([id]) => id === stage);
}

