import type { RunDiffFile } from "../../src/shared/runs.ts";
import type { NativeInspection, NativeRunDriver, NativeSessionIdentity } from "../../src/server/opencode/run-driver.ts";
import type { NativeRunEvent } from "../../src/server/runs/events.ts";

export type FakeMode =
  | "succeed"
  | "succeed-no-diff"
  | "fail"
  | "interrupt"
  | "timeout"
  | "wait"
  | "permission";

export class FakeRunDriver implements NativeRunDriver {
  readonly prompts: string[] = [];
  readonly interrupts: string[] = [];
  readonly createdSessions: Array<{ projectId: string; workspace: string; title: string }> = [];
  mode: FakeMode;
  diff: RunDiffFile[];
  createSessionError: Error | null = null;
  promptError: Error | null = null;
  followError: Error | null = null;
  inspectError: Error | null = null;
  completed: "succeeded" | "failed" | "interrupted" | null = null;
  private release: (() => void) | null = null;
  private permissionRelease: (() => void) | null = null;
  private interruptRelease: (() => void) | null = null;

  constructor(mode: FakeMode = "succeed", diff?: RunDiffFile[]) {
    this.mode = mode;
    this.diff = diff ?? [{ file: "lost-and-found.mjs", status: "modified", additions: 12, deletions: 2 }];
  }

  async createSession(input: { projectId: string; workspace: string; title: string }): Promise<NativeSessionIdentity> {
    if (this.createSessionError) throw this.createSessionError;
    this.createdSessions.push(input);
    return { sessionId: "ses_fake_maker", model: "opencode/deepseek-v4.1-flash-free" };
  }

  async prompt(input: { sessionId: string; text: string }): Promise<{ messageId: string | null }> {
    if (this.promptError) throw this.promptError;
    this.prompts.push(input.text);
    return { messageId: "msg_fake_maker" };
  }

  async interrupt(sessionId: string): Promise<{ interrupted: boolean }> {
    this.interrupts.push(sessionId);
    if (this.mode === "interrupt") {
      this.completed = "interrupted";
      this.interruptRelease?.();
      this.interruptRelease = null;
    }
    return { interrupted: this.mode !== "timeout" };
  }

  async inspect(sessionId: string): Promise<NativeInspection> {
    if (this.inspectError) throw this.inspectError;
    const base = {
      sessionId,
      model: "opencode/deepseek-v4.1-flash-free",
      usage: { cost: 0, input: 12, output: 8, reasoning: 0, cacheRead: 0, cacheWrite: 0 },
    };
    if (this.completed === "succeeded") return { ...base, outcome: "succeeded", idle: true };
    if (this.completed === "failed") return { ...base, outcome: "failed", idle: true };
    if (this.completed === "interrupted") return { ...base, outcome: "interrupted", idle: true };
    if (this.mode === "succeed" || this.mode === "succeed-no-diff") return { ...base, outcome: "succeeded", idle: true };
    if (this.mode === "fail") return { ...base, outcome: "failed", idle: true };
    if (this.mode === "timeout") return { ...base, outcome: null, idle: false };
    return { ...base, outcome: null, idle: false };
  }

  async diff(): Promise<RunDiffFile[]> {
    return this.mode === "succeed-no-diff" ? [] : this.diff;
  }

  async follow(
    sessionId: string,
    onEvent: (event: NativeRunEvent) => void | Promise<void>,
    signal: AbortSignal,
  ): Promise<void> {
    if (this.followError) throw this.followError;
    const emit = (type: string, data: Record<string, unknown> = {}) =>
      onEvent({ type, at: new Date().toISOString(), data: { sessionID: sessionId, ...data } });

    if (this.mode === "succeed" || this.mode === "succeed-no-diff") {
      await emit("session.execution.started");
      await emit("session.tool.called", { name: "edit" });
      await emit("session.text.ended", { text: "Implemented the approved lost-and-found behavior." });
      await emit("session.execution.succeeded");
      this.completed = "succeeded";
      return;
    }
    if (this.mode === "fail") {
      await emit("session.execution.failed");
      this.completed = "failed";
      return;
    }
    if (this.mode === "permission") {
      await emit("permission.asked", { id: "per_1", action: "edit", resources: ["lost-and-found.mjs"] });
      await new Promise<void>((resolve) => {
        this.permissionRelease = resolve;
      });
      await emit("permission.replied", { requestID: "per_1", reply: "once" });
      await emit("session.execution.succeeded");
      this.completed = "succeeded";
      return;
    }
    if (this.mode === "interrupt") {
      await new Promise<void>((resolve) => {
        this.interruptRelease = resolve;
        signal.addEventListener("abort", () => resolve(), { once: true });
      });
      await emit("session.execution.interrupted", { reason: "user" });
      return;
    }
    if (this.mode === "wait") {
      await new Promise<void>((resolve) => {
        this.release = resolve;
        signal.addEventListener("abort", () => resolve(), { once: true });
      });
      await emit("session.execution.succeeded");
      this.completed = "succeeded";
      return;
    }
    // timeout: keep the native session open until the coordinator aborts its
    // local subscription or the caller releases it.
    await new Promise<void>((resolve) => {
      this.release = resolve;
      signal.addEventListener("abort", () => resolve(), { once: true });
    });
  }

  replyToPermission(): void {
    this.permissionRelease?.();
    this.permissionRelease = null;
  }

  finishSuccess(): void {
    this.completed = "succeeded";
    this.release?.();
    this.release = null;
  }

  finishFailure(): void {
    this.completed = "failed";
    this.release?.();
    this.release = null;
  }
}

