import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createApp } from "../../src/server/app.ts";
import { MakerRunService } from "../../src/server/runs/maker-run-service.ts";
import { RunStore } from "../../src/server/runs/store.ts";
import { AtomicProjectStore } from "../../src/server/store/atomic-project-store.ts";
import { contentHash, createProject, projectSchema, refreshNextAction, type Project } from "../../src/server/workflow/model.ts";
import { WorkflowService } from "../../src/server/workflow/service.ts";
import type { RunDiffFile, RunVerification } from "../../src/shared/runs.ts";
import type { FakeRunDriver } from "./fake-run-driver.ts";

export const engine = async () => ({
  available: true as const,
  serverVersion: "2.0.32",
  model: "opencode/deepseek-v4.1-flash-free" as const,
  modelAvailable: true,
  limitation: null,
});

export function approvedProject(directory: string): Project {
  const project = createProject(directory);
  project.product = { status: "APPROVED", proposal: "Track found items for students.", openQuestions: [] };
  project.sections = project.sections.map((section) => {
    const content = `Approved ${section.title} for the lost-and-found workshop.`;
    return {
      ...section,
      content,
      version: 1,
      hash: contentHash(content),
      status: "APPROVED" as const,
    };
  });
  project.makerScope = { status: "GRANTED", statement: "Build the approved lost-and-found behavior in the isolated demo workspace." };
  return refreshNextAction(projectSchema.parse(project));
}

export interface RunFixture {
  directory: string;
  app: ReturnType<typeof createApp>;
  workflow: WorkflowService;
  runStore: RunStore;
  runs: MakerRunService;
  project: Project;
  headers: Record<string, string>;
}

export async function runFixture(
  driver: FakeRunDriver,
  options: {
    timeoutMs?: number;
    cancelObserveMs?: number;
    pollIntervalMs?: number;
    verify?: (input: { workspace: string; diff: RunDiffFile[] }) => Promise<RunVerification>;
    run?: Project;
  } = {},
): Promise<RunFixture> {
  const directory = await mkdtemp(join(tmpdir(), "ub-runs-"));
  const projectStore = new AtomicProjectStore(join(directory, "project.json"));
  const project = options.run ?? approvedProject(directory);
  await projectStore.initialize(project);
  const workflow = new WorkflowService(projectStore);
  const runStore = new RunStore(join(directory, "runs.json"));
  await runStore.initialize();
  const runs = new MakerRunService({
    workflow,
    runStore,
    driver,
    demoWorkspace: directory,
    promptRoot: process.cwd(),
    timeoutMs: options.timeoutMs ?? 2_000,
    cancelObserveMs: options.cancelObserveMs ?? 300,
    pollIntervalMs: options.pollIntervalMs ?? 10,
    verify: options.verify,
  });
  const app = createApp(engine, {
    service: workflow,
    sessionToken: "test-token",
    runs,
    sseHeartbeatMs: 25,
  });
  return {
    directory,
    app,
    workflow,
    runStore,
    runs,
    project,
    headers: { "content-type": "application/json", "x-ub-session-token": "test-token" },
  };
}

export async function waitFor<T>(
  work: () => Promise<T | null | undefined | false>,
  options: { timeoutMs?: number; intervalMs?: number; label?: string } = {},
): Promise<T> {
  const deadline = Date.now() + (options.timeoutMs ?? 3_000);
  while (Date.now() < deadline) {
    const value = await work();
    if (value) return value as T;
    await new Promise((resolve) => setTimeout(resolve, options.intervalMs ?? 10));
  }
  throw new Error(`Timed out waiting for ${options.label ?? "condition"}.`);
}

export function parseSse(text: string): Array<{ event: string; id: string | null; data: unknown }> {
  return text
    .split("\n\n")
    .map((frame) => frame.trim())
    .filter(Boolean)
    .flatMap((frame) => {
      let event = "message";
      let id: string | null = null;
      const data: string[] = [];
      for (const line of frame.split("\n")) {
        if (line.startsWith("event:")) event = line.slice(6).trim();
        else if (line.startsWith("id:")) id = line.slice(3).trim();
        else if (line.startsWith("data:")) data.push(line.slice(5).trim());
      }
      if (data.length === 0) return [];
      try {
        return [{ event, id, data: JSON.parse(data.join("\n")) }];
      } catch {
        return [];
      }
    });
}

