import assert from "node:assert/strict";
import test from "node:test";
import type { RunVerification } from "../src/shared/runs.ts";
import { FakeRunDriver } from "./helpers/fake-run-driver.ts";
import { runFixture, waitFor } from "./helpers/run-fixture.ts";

const passingVerification: RunVerification = {
  checkId: "CK-06",
  result: "PASS",
  fingerprint: "a".repeat(64),
  observedAt: new Date().toISOString(),
  summary: "Node check exit 0. All tests passed.",
  limitation: null,
};

const failingVerification: RunVerification = {
  checkId: "CK-06",
  result: "FAIL",
  fingerprint: "b".repeat(64),
  observedAt: new Date().toISOString(),
  summary: "Node check exit 1. One test failed.",
  limitation: "The native edit did not leave a passing Node test.",
};

function verifyPass() {
  return async () => passingVerification;
}

function startBody(actionId = "run-1") {
  return JSON.stringify({ actionId, expectedRevision: 0 });
}

test("POST /api/runs returns 202 with a saved queued run", async () => {
  const driver = new FakeRunDriver("wait");
  const fixture = await runFixture(driver, { verify: verifyPass() });
  const started = Date.now();
  const response = await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  });
  const elapsed = Date.now() - started;
  assert.equal(response.status, 202);
  const body = await response.json();
  assert.equal(body.run.status, "QUEUED");
  assert.equal(body.duplicate, false);
  assert.ok(elapsed < 500, `acknowledgement took ${elapsed}ms`);
  const saved = await fixture.runStore.get(body.run.id);
  assert.ok(saved);
  assert.equal(saved.projectId, fixture.project.id);
  driver.finishSuccess();
  await waitFor(async () => (await fixture.runStore.get(body.run.id))?.status === "SUCCEEDED");
});

test("duplicate action IDs are idempotent and a second action cannot double-submit", async () => {
  const driver = new FakeRunDriver("wait");
  const fixture = await runFixture(driver, { verify: verifyPass() });
  const first = await fixture.app.request("/api/runs", { method: "POST", headers: fixture.headers, body: startBody("once") });
  assert.equal(first.status, 202);
  const firstBody = await first.json();

  const duplicate = await fixture.app.request("/api/runs", { method: "POST", headers: fixture.headers, body: startBody("once") });
  assert.equal(duplicate.status, 200);
  const duplicateBody = await duplicate.json();
  assert.equal(duplicateBody.duplicate, true);
  assert.equal(duplicateBody.run.id, firstBody.run.id);

  const competing = await fixture.app.request("/api/runs", { method: "POST", headers: fixture.headers, body: startBody("twice") });
  assert.equal(competing.status, 409);
  assert.equal((await competing.json()).code, "RUN_IN_PROGRESS");
  assert.equal(driver.createdSessions.length, 1);
  driver.finishSuccess();
  await waitFor(async () => (await fixture.runStore.get(firstBody.run.id))?.status === "SUCCEEDED");
});

test("cancellation calls the native interrupt and only becomes CANCELLED after observation", async () => {
  const driver = new FakeRunDriver("interrupt");
  const fixture = await runFixture(driver, { verify: verifyPass() });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  })).json();
  const runId = started.run.id;
  await waitFor(async () => (await fixture.runStore.get(runId))?.status === "RUNNING");

  const cancelled = await fixture.app.request(`/api/runs/${runId}/cancel`, {
    method: "POST",
    headers: fixture.headers,
    body: JSON.stringify({ actionId: "cancel-1", expectedRevision: 0 }),
  });
  assert.equal(cancelled.status, 200);
  const body = await cancelled.json();
  assert.equal(body.run.status, "CANCELLED");
  assert.deepEqual(driver.interrupts, ["ses_fake_maker"]);
  assert.ok(body.run.events.some((event: { type: string }) => event.type === "run.interrupt-accepted"));
  assert.ok(body.run.events.some((event: { type: string }) => event.type === "run.cancelled"));
});

test("a timed-out run becomes UNKNOWN with the native session retained, then reconciles", async () => {
  const driver = new FakeRunDriver("timeout");
  const fixture = await runFixture(driver, { timeoutMs: 60, verify: verifyPass() });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  })).json();
  const runId = started.run.id;
  const unknown = await waitFor(async () => {
    const run = await fixture.runStore.get(runId);
    return run?.status === "UNKNOWN" ? run : null;
  }, { label: "timeout UNKNOWN" });
  assert.equal(unknown.sessionId, "ses_fake_maker");
  assert.equal(unknown.messageId, "msg_fake_maker");
  assert.equal(unknown.error?.code, "NATIVE_TIMEOUT");
  assert.equal(driver.prompts.length, 1);

  const reconciled = await fixture.app.request(`/api/runs/${runId}/reconcile`, {
    method: "POST",
    headers: fixture.headers,
    body: JSON.stringify({ actionId: "reconcile-1", expectedRevision: 0 }),
  });
  assert.equal(reconciled.status, 200);
  const body = await reconciled.json();
  assert.equal(body.run.status, "SUCCEEDED");
  assert.equal(body.run.diff.length, 1);
  assert.equal(driver.prompts.length, 1, "reconciliation must not send a second prompt");
});

test("known native failures stay FAILED with stable codes", async () => {
  const cases = [
    ["fetch failed", "OPENCODE_UNAVAILABLE", "create"],
    ["401 Unauthorized", "AUTHENTICATION_FAILED", "create"],
    ["429 provider limit", "PROVIDER_LIMIT", "prompt"],
    ["model not found", "MODEL_UNAVAILABLE", "create"],
  ] as const;
  for (const [message, code, stage] of cases) {
    const driver = new FakeRunDriver("succeed");
    if (stage === "create") driver.createSessionError = new Error(message);
    else driver.promptError = new Error(message);
    const fixture = await runFixture(driver, { verify: verifyPass() });
    const started = await (await fixture.app.request("/api/runs", {
      method: "POST",
      headers: fixture.headers,
      body: startBody(`run-${code}`),
    })).json();
    const failed = await waitFor(async () => {
      const run = await fixture.runStore.get(started.run.id);
      return run?.status === "FAILED" ? run : null;
    }, { label: code });
    assert.equal(failed.error?.code, code, message);
    assert.equal(driver.prompts.length, stage === "prompt" ? 0 : 0);
  }
});

test("a native permission wait is visible and a denial ends FAILED", async () => {
  const driver = new FakeRunDriver("permission-denied");
  const fixture = await runFixture(driver, { verify: verifyPass() });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  })).json();
  const waiting = await waitFor(async () => {
    const run = await fixture.runStore.get(started.run.id);
    return run?.status === "WAITING_PERMISSION" ? run : null;
  }, { label: "permission wait" });
  assert.equal(waiting.permission?.action, "edit");
  driver.replyToPermission();
  const failed = await waitFor(async () => {
    const run = await fixture.runStore.get(started.run.id);
    return run?.status === "FAILED" ? run : null;
  }, { label: "permission denial" });
  assert.ok(failed.events.some((event) => event.type === "permission.replied"));
});

test("a failed verification keeps the diff and records FAIL", async () => {
  const driver = new FakeRunDriver("succeed");
  const fixture = await runFixture(driver, { verify: async () => failingVerification });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  })).json();
  const failed = await waitFor(async () => {
    const run = await fixture.runStore.get(started.run.id);
    return run?.status === "FAILED" ? run : null;
  }, { label: "verification failure" });
  assert.equal(failed.verification?.result, "FAIL");
  assert.equal(failed.diff.length, 1);
  assert.match(failed.limitation ?? "", /passing Node test/);
});

test("an unexpected native event is recorded without crashing the run", async () => {
  const driver = new FakeRunDriver("malformed");
  const fixture = await runFixture(driver, { verify: verifyPass() });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: startBody(),
  })).json();
  const succeeded = await waitFor(async () => {
    const run = await fixture.runStore.get(started.run.id);
    return run?.status === "SUCCEEDED" ? run : null;
  }, { label: "malformed event tolerance" });
  assert.ok(succeeded.events.some((event) => event.type === "native.other"));
  assert.ok(!JSON.stringify(succeeded.events).includes("session.reasoning"));
});

