import test from "node:test";
import { canTransitionRun } from "../src/shared/runs.ts";
import { normalizeNativeEvent } from "../src/server/runs/events.ts";
import { classifyNativeError, redactMetadataObject, redactString } from "../src/server/runs/redaction.ts";

test("run state transitions reject invalid moves and keep UNKNOWN reconcilable", () => {
  assert.equal(canTransitionRun("QUEUED", "CONNECTING"), true);
  assert.equal(canTransitionRun("CONNECTING", "RUNNING"), true);
  assert.equal(canTransitionRun("RUNNING", "WAITING_PERMISSION"), true);
  assert.equal(canTransitionRun("WAITING_PERMISSION", "RUNNING"), true);
  assert.equal(canTransitionRun("VERIFYING", "SUCCEEDED"), true);
  assert.equal(canTransitionRun("SUCCEEDED", "RUNNING"), false);
  assert.equal(canTransitionRun("CANCELLED", "UNKNOWN"), false);
  assert.equal(canTransitionRun("QUEUED", "RUNNING"), false);
  assert.equal(canTransitionRun("UNKNOWN", "SUCCEEDED"), true);
  assert.equal(canTransitionRun("UNKNOWN", "QUEUED"), false);
});

test("native events become public summaries without tool arguments or reasoning", () => {
  const tool = normalizeNativeEvent({
    type: "session.tool.called",
    data: {
      name: "edit",
      input: { password: "REDACTED", authorization: "Bearer abcdefghijklmnop" },
    },
  });
  assert.equal(tool.category, "tool");
  assert.match(tool.summary, /Using tool edit/);
  assert.equal(JSON.stringify(tool).includes("REDACTED"), false);
  assert.equal(JSON.stringify(tool).includes("abcdefghijklmnop"), false);

  const reasoning = normalizeNativeEvent({
    type: "session.reasoning.ended",
    data: { text: "hidden chain of thought" },
  });
  assert.equal(reasoning.type, "native.other");
  assert.equal(JSON.stringify(reasoning).includes("hidden chain of thought"), false);

  const permission = normalizeNativeEvent({
    type: "permission.asked",
    data: { id: "per_1", action: "edit", resources: ["token=secret-value"] },
  });
  assert.equal(permission.status, "WAITING_PERMISSION");
  assert.equal(permission.permission?.requestId, "per_1");
  assert.equal(JSON.stringify(permission).includes("secret-value"), false);
});

test("malformed native events become a safe error event", () => {
  const event = normalizeNativeEvent({ type: "session.text.ended", data: { text: 42 }, malformed: true });
  assert.equal(event.category, "error");
  assert.equal(event.type, "native.malformed");
  assert.match(event.summary, /malformed native event/i);
});

test("event and telemetry strings redact secrets", () => {
  const redacted = redactString("Authorization: Bearer abcdefghijklmnop password=REDACTED api_key=REDACTED token=abc123");
  assert.equal(redacted.includes("abcdefghijklmnop"), false);
  assert.equal(redacted.includes("REDACTED"), false);
  assert.equal(redacted.includes("REDACTED"), false);
  assert.equal(redacted.includes("abc123"), false);
  assert.match(redacted, /\[REDACTED/);

  const metadata = redactMetadataObject({
    authorization: "Bearer abcdefghijklmnop",
    nested: { password: "REDACTED", safe: "visible" },
    cookie: "session=abc",
  });
  assert.equal(JSON.stringify(metadata).includes("abcdefghijklmnop"), false);
  assert.equal(JSON.stringify(metadata).includes("REDACTED"), false);
  assert.equal(JSON.stringify(metadata).includes("session=abc"), false);
  assert.equal(metadata.nested && (metadata.nested as Record<string, unknown>).safe, "visible");
});

test("native errors classify into stable user-facing codes", () => {
  assert.equal(classifyNativeError(new Error("401 Unauthorized")).code, "AUTHENTICATION_FAILED");
  assert.equal(classifyNativeError(new Error("429 rate limit")).code, "PROVIDER_LIMIT");
  assert.equal(classifyNativeError(new Error("model not found")).code, "MODEL_UNAVAILABLE");
  assert.equal(classifyNativeError(new Error("fetch failed")).code, "OPENCODE_UNAVAILABLE");
  assert.equal(classifyNativeError(new Error("permission denied")).code, "PERMISSION_DENIED");
});

import assert from "node:assert/strict";
import test from "node:test";
import type { RunVerification } from "../src/shared/runs.ts";
import { FakeRunDriver } from "./helpers/fake-run-driver.ts";
import { parseSse, runFixture, waitFor } from "./helpers/run-fixture.ts";

const verification: RunVerification = {
  checkId: "CK-06",
  result: "PASS",
  fingerprint: "c".repeat(64),
  observedAt: new Date().toISOString(),
  summary: "Node check exit 0.",
  limitation: null,
};

async function finishedRun() {
  const driver = new FakeRunDriver("succeed");
  const fixture = await runFixture(driver, { verify: async () => verification });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: JSON.stringify({ actionId: "sse-run", expectedRevision: 0 }),
  })).json();
  await waitFor(async () => (await fixture.runStore.get(started.run.id))?.status === "SUCCEEDED");
  return { fixture, runId: started.run.id as string };
}

test("SSE replays ordered events, then a terminal close frame", async () => {
  const { fixture, runId } = await finishedRun();
  const response = await fixture.app.request(`/api/runs/${runId}/events?token=test-token`);
  assert.equal(response.status, 200);
  assert.match(response.headers.get("content-type") ?? "", /text\/event-stream/);
  const frames = parseSse(await response.text());
  assert.equal(frames[0]?.event, "snapshot");
  const events = frames.filter((frame) => frame.event === "run-event");
  assert.ok(events.length >= 4);
  const sequences = events.map((event) => (event.data as { seq: number }).seq);
  assert.deepEqual(sequences, [...sequences].sort((left, right) => left - right));
  assert.equal(new Set(sequences).size, sequences.length);
  assert.equal(frames.at(-1)?.event, "close");
  assert.equal((frames.at(-1)?.data as { status: string }).status, "SUCCEEDED");
});

test("SSE resumes from a cursor without replaying older events", async () => {
  const { fixture, runId } = await finishedRun();
  const run = await fixture.runStore.get(runId);
  assert.ok(run);
  const cursor = run.events[2]?.seq ?? 1;
  const response = await fixture.app.request(`/api/runs/${runId}/events?after=${cursor}&token=test-token`);
  const frames = parseSse(await response.text());
  const events = frames.filter((frame) => frame.event === "run-event");
  assert.ok(events.length > 0);
  for (const event of events) {
    assert.ok((event.data as { seq: number }).seq > cursor);
  }
});

test("SSE resynchronizes a cursor outside the retained event range", async () => {
  const { fixture, runId } = await finishedRun();
  const run = await fixture.runStore.get(runId);
  assert.ok(run);
  const response = await fixture.app.request(`/api/runs/${runId}/events?after=99999&token=test-token`);
  const frames = parseSse(await response.text());
  assert.equal(frames[0]?.event, "snapshot");
  assert.ok(frames.some((frame) => frame.event === "resync"));
  const resync = frames.find((frame) => frame.event === "resync");
  assert.equal((resync?.data as { reason: string }).reason, "cursor-ahead");
  const events = frames.filter((frame) => frame.event === "run-event");
  assert.deepEqual(
    events.map((event) => (event.data as { seq: number }).seq),
    run.events.map((event) => event.seq),
  );
});

test("SSE sends heartbeats while a run is active", async () => {
  const driver = new FakeRunDriver("wait");
  const fixture = await runFixture(driver, { verify: async () => verification });
  const started = await (await fixture.app.request("/api/runs", {
    method: "POST",
    headers: fixture.headers,
    body: JSON.stringify({ actionId: "heartbeat-run", expectedRevision: 0 }),
  })).json();
  await waitFor(async () => (await fixture.runStore.get(started.run.id))?.status === "RUNNING");
  const controller = new AbortController();
  const response = await fixture.app.request(`/api/runs/${started.run.id}/events?token=test-token`, {
    signal: controller.signal,
  });
  const reader = response.body?.getReader();
  assert.ok(reader);
  const decoder = new TextDecoder();
  let buffer = "";
  const deadline = Date.now() + 2_000;
  let sawHeartbeat = false;
  try {
    while (Date.now() < deadline && !sawHeartbeat) {
      const chunk = await reader.read();
      if (chunk.done) break;
      buffer += decoder.decode(chunk.value, { stream: true });
      sawHeartbeat = buffer.includes("event: heartbeat");
    }
  } finally {
    controller.abort();
    await reader.cancel().catch(() => undefined);
    driver.finishSuccess();
  }
  assert.equal(sawHeartbeat, true);
  await waitFor(async () => (await fixture.runStore.get(started.run.id))?.status === "SUCCEEDED");
});

test("SSE requires the local session token", async () => {
  const { fixture, runId } = await finishedRun();
  const response = await fixture.app.request(`/api/runs/${runId}/events`);
  assert.equal(response.status, 403);
});

import assert from "node:assert/strict";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
