import { RunStore } from "../src/server/runs/store.ts";
import { AtomicProjectStore } from "../src/server/store/atomic-project-store.ts";
import { createProject, projectSchema } from "../src/server/workflow/model.ts";
import { WorkflowService } from "../src/server/workflow/service.ts";
import type { RunVerification } from "../src/shared/runs.ts";
import { FakeRunDriver } from "./helpers/fake-run-driver.ts";
import { approvedProject, waitFor } from "./helpers/run-fixture.ts";

const verification: RunVerification = {
  checkId: "CK-06",
  result: "PASS",
  fingerprint: "d".repeat(64),
  observedAt: new Date().toISOString(),
  summary: "Node check exit 0.",
  limitation: null,
};

test("restart reconciles a saved running session without sending a second prompt", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-restart-"));
  const projectStore = new AtomicProjectStore(join(directory, "project.json"));
  const project = approvedProject(directory);
  await projectStore.initialize(project);
  const workflow = new WorkflowService(projectStore);
  const runStore = new RunStore(join(directory, "runs.json"));
  await runStore.initialize();
  const driver = new FakeRunDriver("wait");
  const runs = new MakerRunService({
    workflow,
    runStore,
    driver,
    demoWorkspace: directory,
    promptRoot: process.cwd(),
    timeoutMs: 1_000,
    pollIntervalMs: 10,
    verify: async () => verification,
  });

  const created = await runStore.create({
    projectId: project.id,
    actionId: "before-restart",
    payloadHash: "hash",
    workspace: directory,
  });
  await runStore.transition(created.id, "CONNECTING", {}, {
    category: "connection",
    type: "run.connecting",
    summary: "Connecting.",
  });
  await runStore.update(created.id, (run) => ({ ...run, sessionId: "ses_saved", model: "opencode/deepseek-v4.1-flash-free" }));
  await runStore.transition(created.id, "RUNNING", {}, {
    category: "run",
    type: "run.running",
    summary: "Running.",
  });
  await runStore.update(created.id, (run) => ({ ...run, messageId: "msg_saved" }));

  const recovered = await runs.recover();
  assert.equal(recovered.length, 1);
  assert.equal(driver.prompts.length, 0, "recovery must not prompt again");
  const running = await runStore.get(created.id);
  assert.ok(running);
  assert.equal(running.sessionId, "ses_saved");
  assert.equal(running.messageId, "msg_saved");
  assert.equal(running.status, "RUNNING");

  driver.finishSuccess();
  const succeeded = await waitFor(async () => {
    const run = await runStore.get(created.id);
    return run?.status === "SUCCEEDED" ? run : null;
  }, { label: "recovered run success" });
  assert.equal(succeeded.sessionId, "ses_saved");
  assert.equal(driver.prompts.length, 0);
});

test("restart marks a run without a native session as retryable, not silently retried", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-restart-no-session-"));
  const projectStore = new AtomicProjectStore(join(directory, "project.json"));
  const project = approvedProject(directory);
  await projectStore.initialize(project);
  const runStore = new RunStore(join(directory, "runs.json"));
  await runStore.initialize();
  const driver = new FakeRunDriver("succeed");
  const runs = new MakerRunService({
    workflow: new WorkflowService(projectStore),
    runStore,
    driver,
    demoWorkspace: directory,
    promptRoot: process.cwd(),
    verify: async () => verification,
  });
  const created = await runStore.create({
    projectId: project.id,
    actionId: "queued-before-restart",
    payloadHash: "hash",
    workspace: directory,
  });
  await runs.recover();
  const failed = await waitFor(async () => {
    const run = await runStore.get(created.id);
    return run?.status === "FAILED" ? run : null;
  }, { label: "no-session restart" });
  assert.equal(failed.error?.code, "INTERRUPTED_BY_RESTART");
  assert.equal(failed.sessionId, null);
  assert.equal(driver.prompts.length, 0);
});

test("a version 1 project migrates forward and keeps a pre-migration backup", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-migration-"));
  const path = join(directory, "project.json");
  const legacy = createProject("/workspace") as Record<string, unknown>;
  legacy.schemaVersion = 1;
  delete legacy.runIds;
  legacy.operations = [];
  await writeFile(path, `${JSON.stringify(legacy, null, 2)}\n`, "utf8");
  const store = new AtomicProjectStore(path);
  const loaded = await store.load();
  assert.equal(loaded.state.schemaVersion, 2);
  assert.deepEqual(loaded.state.runIds, []);
  const backup = await readFile(`${path}.v1.bak`, "utf8");
  assert.equal(JSON.parse(backup).schemaVersion, 1);
  await store.save(0, loaded.state);
  const previous = await readFile(`${path}.previous`, "utf8");
  assert.equal(projectSchema.parse(JSON.parse(previous)).schemaVersion, 2);
});

test("the run store keeps a previous snapshot for corrupt-current recovery", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-run-backup-"));
  const path = join(directory, "runs.json");
  const store = new RunStore(path);
  await store.initialize();
  const run = await store.create({
    projectId: "project",
    actionId: "action",
    payloadHash: "hash",
    workspace: directory,
  });
  await store.appendEvent(run.id, {
    category: "run",
    type: "run.test",
    summary: "A safe event.",
  });
  const previous = await readFile(store.previousPath, "utf8");
  assert.ok(previous.includes(run.id));
});

