function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  return "internal_error";
}

export function redactForTelemetry(value: unknown): string {
  return redactString(value instanceof Error ? value.message : String(value ?? ""), 1_000);
}

/**
 * Sentry events are sanitized at the boundary as well as at each event writer.
 * Prompts, cookies, authorization headers and secret-looking values never leave
 * the process through error telemetry.
 */
export function sanitizeSentryEvent<T>(event: T): T {
  if (!event || typeof event !== "object") return event;
  const candidate = event as Record<string, unknown>;
  if (typeof candidate.message === "string") candidate.message = redactString(candidate.message, 1_000);
  const exception = candidate.exception as { values?: Array<{ value?: unknown }> } | undefined;
  if (exception?.values) {
    for (const value of exception.values) {
      if (typeof value.value === "string") value.value = redactString(value.value, 1_000);
    }
