private async write(document: RunDocument): Promise<void> {
  await mkdir(dirname(this.path), { recursive: true });
  const validated = runDocumentSchema.parse(document);
  const temporaryPath = `${this.path}.tmp-${process.pid}-${Date.now()}`;
  let currentIsValid = false;
  try {
    JSON.parse(await readFile(this.path, "utf8"));
    currentIsValid = true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      // Keep the corrupt original instead of overwriting the last good backup.
      await copyFile(this.path, `${this.path}.corrupt-${Date.now()}`).catch(() => undefined);
    }
  }
  if (currentIsValid) {
    await copyFile(this.path, this.previousPath);
  }
  await writeFile(temporaryPath, `${JSON.stringify(validated, null, 2)}\n`, { flag: "wx" });
  await rename(temporaryPath, this.path);
}

